COMPENDIUM.parts[1] = /*JSON-START*/{
  "part": 2, "slug": "kutsal-sirlar", "tr": "Hristiyan Gizeminin Kutlanması", "en": "The Celebration of the Christian Mystery", "from": 218, "to": 356,
  "items": [
    { "type": "heading", "level": 1, "id": "ikinci-kisim-hristiyan-gizeminin-kutlanmasi",
      "tr": "İkinci Kısım: Hristiyan Gizeminin Kutlanması",
      "en": "Part Two: The Celebration of the Christian Mystery" },
    { "type": "heading", "level": 2, "id": "birinci-bolum-kutsal-sirlar-duzeni",
      "tr": "Birinci Bölüm: Kutsal Sırlar Düzeni",
      "en": "Section One: The Sacramental Economy" },
    { "type": "qa", "n": 218, "id": "soru-218", "ccc": "1066–1070",
      "tr": { "q": "Litürji nedir?",
              "a": "Litürji, Mesih’in gizeminin ve özellikle O’nun Paskalya gizeminin kutlanmasıdır. Litürji, İsa Mesih’in rahiplik görevinin yerine getirilmesi yoluyla insanlığın kutsallaşmasını işaretlerle gösterir ve gerçekleştirir.\nTanrı’ya yaraşan kamusal tapınma, Mesih’in Gizemli Bedeni, yani O’nun başı ve üyeleri tarafından sunulur." },
      "en": { "q": "What is the liturgy?",
              "a": "The liturgy is the celebration of the mystery of Christ and in particular his paschal mystery. Through the exercise of the priestly office of Jesus Christ the liturgy manifests in signs and brings about the sanctification of humankind.\nThe public worship which is due to God is offered by the Mystical Body of Christ, that is, by its head and by its members." } },
    { "type": "qa", "n": 219, "id": "soru-219", "ccc": "1071–1075",
      "tr": { "q": "Litürji Kilise’nin yaşamında nasıl bir yer tutar?",
              "a": "Litürji, <em>en üstün</em> kutsal eylem olarak, Kilise’nin etkinliğinin yöneldiği doruk ve aynı zamanda onun bütün gücünün aktığı kaynaktır. Mesih, litürji aracılığıyla, Kilisesi’nde, Kilisesi’yle ve Kilisesi aracılığıyla kurtuluşumuzun işini sürdürür." },
      "en": { "q": "What place does the liturgy occupy in the life of the Church?",
              "a": "The liturgy as the sacred action <em>par excellence</em> is the summit toward which the activity of the Church is directed and it is likewise the font from which all her power flows. Through the liturgy Christ continues the work of our redemption in, with and through his Church." } },
    { "type": "qa", "n": 220, "id": "soru-220", "ccc": "1076",
      "tr": { "q": "Kutsal sırlar düzeni neden oluşur?",
              "a": "Kutsal sırlar düzeni (sakramental ekonomi), Mesih’in kurtarışının meyvelerinin, Kilise’nin kutsal sırlarının, özellikle de Efkaristiya’nın kutlanmasıyla, “O gelinceye dek” (1 Korintliler 11:26) iletilmesinden oluşur." },
      "en": { "q": "In what does the sacramental economy consist?",
              "a": "The sacramental economy consists in the communication of the fruits of Christ’s redemption through the celebration of the sacraments of the Church, most especially that of the Eucharist, “until he comes” (<em>1 Corinthians</em> 11:26)." } },
    { "type": "heading", "level": 3, "id": "birinci-baslik-kilise-caginda-paskalya-gizemi",
      "tr": "Birinci Başlık: Kilise Çağında Paskalya Gizemi",
      "en": "Chapter One: The Paschal Mystery in the Age of the Church" },
    { "type": "heading", "level": 4, "id": "liturji-en-kutsal-uclunun-isi",
      "tr": "Litürji: En Kutsal Üçlü’nün İşi",
      "en": "The Liturgy - Work of the Most Holy Trinity" },
    { "type": "qa", "n": 221, "id": "soru-221", "ccc": "1077–1083, 1110",
      "tr": { "q": "Baba, litürjinin kaynağı ve hedefi hangi anlamda olur?",
              "a": "Litürji aracılığıyla Baba, bizim için ölen ve dirilen beden almış Söz’de bizi nimetleriyle doldurur ve yüreklerimize Kutsal Ruh’u döker. Aynı zamanda Kilise de tapınmasıyla, övgüsüyle ve şükranıyla Baba’yı över ve O’ndan Oğlu’nun ve Kutsal Ruh’un armağanını diler." },
      "en": { "q": "In what way is the Father the source and the goal of the liturgy?",
              "a": "Through the liturgy the Father fills us with his blessings in the Word made flesh who died and rose for us and pours into our hearts the Holy Spirit. At the same time, the Church blesses the Father by her worship, praise, and thanksgiving and begs him for the gift of his Son and the Holy Spirit." } },
    { "type": "qa", "n": 222, "id": "soru-222", "ccc": "1084–1090",
      "tr": { "q": "Mesih’in litürjideki işi nedir?",
              "a": "Kilise’nin litürjisinde Mesih’in işaret ettiği ve mevcut kıldığı, Kendi Paskalya gizemidir. Havarilerine Kutsal Ruh’u vererek, onlara ve ardıllarına, kurtuluş işini Efkaristiya kurbanı ve kutsal sırlar aracılığıyla mevcut kılma yetkisini emanet etti; bu sırlarda O’nun Kendisi, lütfunu bütün dünyada her zamanın ve her yerin inanlılarına iletmek için etkin olur." },
      "en": { "q": "What is the work of Christ in the liturgy?",
              "a": "In the liturgy of the Church, it is his own paschal mystery that Christ signifies and makes present. By giving the Holy Spirit to his apostles he entrusted to them and their successors the power to make present the work of salvation through the Eucharistic sacrifice and the sacraments, in which he himself acts to communicate his grace to the faithful of all times and places throughout the world." } },
    { "type": "qa", "n": 223, "id": "soru-223", "ccc": "1091–1109, 1112",
      "tr": { "q": "Kutsal Ruh Kilise’nin litürjisinde nasıl etkinlik gösterir?",
              "a": "Litürjide Kutsal Ruh ile Kilise arasında en yakın işbirliği işler. Kutsal Ruh Kilise’yi Rabbiyle karşılaşmaya hazırlar. Mesih’i topluluğun imanına hatırlatır ve gösterir. Mesih’in gizemini gerçekten mevcut kılar. Kilise’yi Mesih’in yaşamı ve göreviyle birleştirir ve birlik armağanının Kilise’de meyve vermesini sağlar." },
      "en": { "q": "How does the Holy Spirit work in the liturgy of the Church?",
              "a": "The very closest cooperation is at work in the liturgy between the Holy Spirit and the Church. The Holy Spirit prepares the Church to encounter her Lord. He recalls and manifests Christ to the faith of the assembly. He makes the mystery of Christ really present. He unites the Church to the life and mission of Christ and makes the gift of communion bear fruit in the Church." } },
    { "type": "heading", "level": 4, "id": "kilisenin-kutsal-sirlarinda-paskalya-gizemi",
      "tr": "Kilise’nin Kutsal Sırlarında Paskalya Gizemi",
      "en": "The Paschal Mystery in the Sacraments of the Church" },
    { "type": "qa", "n": 224, "id": "soru-224", "ccc": "1113–1131",
      "tr": { "q": "Kutsal sırlar nedir ve hangileridir?",
              "a": "Mesih tarafından kurulan ve Kilise’ye emanet edilen kutsal sırlar (sakramentler), duyularla algılanabilen, lütfun etkin işaretleridir. Onlar aracılığıyla bize tanrısal yaşam bağışlanır. Yedi kutsal sır vardır: Vaftiz, Konfirmasyon (Güçlendirme), Kutsal Efkaristiya, Tövbe (Barışma), Hastaların Meshedilmesi, Kutsal Rahiplik ve Evlilik." },
      "en": { "q": "What are the sacraments and which are they?",
              "a": "The sacraments, instituted by Christ and entrusted to the Church, are efficacious signs of grace perceptible to the senses. Through them divine life is bestowed upon us. There are seven sacraments: Baptism, Confirmation, Holy Eucharist, Penance, Anointing of the Sick, Holy Orders, and Matrimony." } },
    { "type": "qa", "n": 225, "id": "soru-225", "ccc": "1114–1116",
      "tr": { "q": "Kutsal sırların Mesih’le ilişkisi nedir?",
              "a": "Mesih’in yaşamının gizemleri, O’nun bundan böyle Kilisesi’nin görevlileri aracılığıyla kutsal sırlarda dağıtacağı şeylerin temelleridir." },
      "en": { "q": "What is the relationship of the sacraments to Christ?",
              "a": "The mysteries of Christ’s life are the foundations of what he would henceforth dispense in the sacraments, through the ministers of his Church." } },
    { "type": "quote",
      "tr": "“Kurtarıcımızda görünür olan, O’nun gizemlerine geçmiştir.” ([[Büyük Aziz Leo|Saint Leo the Great]])",
      "en": "“What was visible in our Savior has passed over into his mysteries.”  (Saint Leo the Great)" },
    { "type": "qa", "n": 226, "id": "soru-226", "ccc": "1117–1119",
      "tr": { "q": "Kutsal sırlar ile Kilise arasındaki bağ nedir?",
              "a": "Mesih kutsal sırları Kilisesi’ne emanet etmiştir. Onlar iki anlamda “Kilise’nin” kutsal sırlarıdır: Mesih’in eyleminin sırrı olan Kilise’nin eylemleri oldukları ölçüde “ondandırlar”; ve Kilise’yi bina ettikleri ölçüde “onun içindirler”." },
      "en": { "q": "What is the link between the sacraments and the Church?",
              "a": "Christ has entrusted the sacraments to his Church. They are the sacraments “of the Church” in a twofold sense: they are “from her” insofar as they are actions of the Church which is the sacrament of Christ’s action; and they are “for her” in as much as they build up the Church." } },
    { "type": "qa", "n": 227, "id": "soru-227", "ccc": "1121",
      "tr": { "q": "<em>Kutsal sır</em> mührü (karakteri) nedir?",
              "a": "Bu, Vaftiz, Konfirmasyon ve Kutsal Rahiplik sırları tarafından verilen ruhsal bir “<em>mühür</em>”dür. Tanrısal korumanın bir vaadi ve güvencesidir. Bu mühür sayesinde Hristiyan Mesih’e benzetilir, çeşitli yollarla O’nun rahipliğine katılır ve farklı durumlara ve görevlere göre Kilise’de yerini alır. Bu nedenle tanrısal tapınma ve Kilise’nin hizmeti için ayrılmıştır. Bu mühür silinmez olduğu için, onu cana basan kutsal sırlar yaşamda yalnızca bir kez alınır." },
      "en": { "q": "What is the <em>sacramental</em> character?",
              "a": "It is a spiritual “<em>seal</em>” bestowed by the sacraments of Baptism, Confirmation, and Holy Orders. It is a promise and guarantee of divine protection. By virtue of this seal the Christian is configured to Christ, participates in a variety of ways in his priesthood and takes his part in the Church according to different states and functions. He is, therefore, set apart for divine worship and the service of the Church. Because this character is indelible the sacraments that impress it on the soul are received only once in life." } },
    { "type": "qa", "n": 228, "id": "soru-228", "ccc": "1122–1126, 1133",
      "tr": { "q": "Kutsal sırlar ile iman arasındaki ilişki nedir?",
              "a": "Kutsal sırlar yalnızca imanı önceden varsaymakla kalmaz, aynı zamanda sözlerle ve ayin öğeleriyle onu besler, güçlendirir ve ifade eder. Kilise kutsal sırları kutlayarak havarilerden gelen imanı ikrar eder. Eski “<em>lex orandi, lex credendi</em>” (duanın yasası, imanın yasasıdır) sözünün kökeni buradan gelir; yani Kilise dua ettiği gibi inanır." },
      "en": { "q": "What is the relationship between the sacraments and faith?",
              "a": "The sacraments not only presuppose faith but with words and ritual elements they nourish, strengthen, and express it. By celebrating the sacraments, the Church professes the faith that comes from the apostles. This explains the origin of the ancient saying, “<em>lex orandi, lex credendi,</em>” that is, the Church believes as she prays." } },
    { "type": "qa", "n": 229, "id": "soru-229", "ccc": "1127–1128, 1131",
      "tr": { "q": "Kutsal sırlar neden etkindir?",
              "a": "Kutsal sırlar <em>ex opere operato</em> (“kutsal sır eyleminin yerine getirilmesiyle”) etkindir; çünkü kutsal sırlarda etkin olan ve onların işaret ettiği lütfu ileten Mesih’tir. Kutsal sırların etkinliği, görevlinin kişisel kutsallığına bağlı değildir. Ancak kutsal sırların meyveleri, onları alan kişinin iç hazırlığına bağlıdır." },
      "en": { "q": "Why are the sacraments efficacious?",
              "a": "The sacraments are efficacious <em>ex opere operato </em>(“by the very fact that the sacramental action is performed”) because it is Christ who acts in the sacraments and communicates the grace they signify. The efficacy of the sacraments does not depend upon the personal holiness of the minister. However, the fruits of the sacraments do depend on the dispositions of the one who receives them." } },
    { "type": "qa", "n": 230, "id": "soru-230", "ccc": "1129",
      "tr": { "q": "Kutsal sırlar hangi nedenle kurtuluş için gereklidir?",
              "a": "Mesih’e inananlar için kutsal sırlar, her inanlıya hepsi verilmese bile, kurtuluş için gereklidir; çünkü kutsal sır lütfunu, günahların bağışlanmasını, Tanrı’nın çocukları olarak evlatlığa kabulü, Rab Mesih’e benzeşmeyi ve Kilise’ye üyeliği sağlarlar. Kutsal Ruh, kutsal sırları alanları iyileştirir ve dönüştürür." },
      "en": { "q": "For what reason are the sacraments necessary for salvation?",
              "a": "For believers in Christ the sacraments, even if they are not all given to each of the faithful, are necessary for salvation because they confer sacramental grace, forgiveness of sins, adoption as children of God, conformation to Christ the Lord and membership in the Church. The Holy Spirit heals and transforms those who receive the sacraments." } },
    { "type": "qa", "n": 231, "id": "soru-231", "ccc": "1129, 1131, 1134, 2003",
      "tr": { "q": "Kutsal sır lütfu nedir?",
              "a": "Kutsal sır lütfu, Mesih tarafından verilen ve her kutsal sırra özgü olan Kutsal Ruh’un lütfudur. Bu lütuf inanlılara kutsallığa doğru yolculuklarında yardım eder; böylece Kilise’nin de sevgide ve dünyaya tanıklığında büyümesine katkıda bulunur." },
      "en": { "q": "What is sacramental grace?",
              "a": "Sacramental grace is the grace of the Holy Spirit which is given by Christ and is proper to each sacrament. This grace helps the faithful in their journey toward holiness and so assists the Church as well to grow in charity and in her witness to the world." } },
    { "type": "qa", "n": 232, "id": "soru-232", "ccc": "1130",
      "tr": { "q": "Kutsal sırlar ile sonsuz yaşam arasındaki ilişki nedir?",
              "a": "Kilise, kutsal sırlarda, “mutlu umudumuzun gerçekleşmesini, yüce Tanrımız ve Kurtarıcımız Mesih İsa’nın yücelik içinde görünmesini beklerken” (Titus 2:13), şimdiden sonsuz yaşamın önden tadını alır." },
      "en": { "q": "What is the relationship between the sacraments and everlasting life?",
              "a": "In the sacraments the Church already receives a foretaste of eternal life, while “awaiting in blessed hope, the appearing in glory of our great God and saviour Christ Jesus” (<em>Titus</em> 2:13)." } },
    { "type": "heading", "level": 3, "id": "ikinci-baslik-paskalya-gizeminin-kutsal-sirlarla-kutlanmasi",
      "tr": "İkinci Başlık: Paskalya Gizeminin Kutsal Sırlarla Kutlanması",
      "en": "Chapter Two: The Sacramental Celebration of the Paschal Mystery" },
    { "type": "heading", "level": 4, "id": "kilisenin-liturjisini-kutlamak",
      "tr": "Kilise’nin Litürjisini Kutlamak",
      "en": "Celebrating the Liturgy of the Church" },
    { "type": "heading", "level": 5, "id": "kim-kutlar",
      "tr": "Kim kutlar?",
      "en": "Who celebrates?" },
    { "type": "qa", "n": 233, "id": "soru-233", "ccc": "1135–1137, 1187",
      "tr": { "q": "Litürjide kim etkindir?",
              "a": "Litürjide etkin olan, Baş ve Beden olarak <em>bütün Mesih</em>’tir (<em>Christus Totus</em>). Başkâhinimiz olarak O, gökte ve yeryüzünde Kilise olan bedeniyle birlikte kutlar." },
      "en": { "q": "Who acts in the liturgy?",
              "a": "In the liturgy it is the <em>whole Christ</em> (<em>Christus Totus</em>) who acts, Head and Body. As our High Priest he celebrates with his body, which is the Church in heaven and on earth." } },
    { "type": "qa", "n": 234, "id": "soru-234", "ccc": "1138–1139",
      "tr": { "q": "Göksel litürjiyi kim kutlar?",
              "a": "Göksel litürjiyi melekler, Eski ve Yeni Antlaşma’nın azizleri, özellikle Tanrı’nın Annesi, Havariler, şehitler ve “her ulustan, her oymaktan, her halktan, her dilden, kimsenin sayamayacağı büyük bir kalabalık” (Vahiy 7:9) kutlar. Kurtuluşumuzun gizemini kutsal sırlarda kutladığımızda bu sonsuz litürjiye katılırız." },
      "en": { "q": "Who celebrates the heavenly liturgy?",
              "a": "The heavenly liturgy is celebrated by the angels, by the saints of the Old and New Testament, particularly the Mother of God, by the Apostles, by the martyrs, and by the “great multitude which no one could number from every nation, race, people, and tongue.” (<em>Revelation</em> 7:9). When we celebrate the mystery of our salvation in the sacraments we participate in this eternal liturgy." } },
    { "type": "qa", "n": 235, "id": "soru-235", "ccc": "1140–1144, 1188",
      "tr": { "q": "Yeryüzündeki Kilise litürjiyi nasıl kutlar?",
              "a": "Yeryüzündeki Kilise litürjiyi, her birinin Kutsal Ruh’un birliği içinde kendi görevine göre hareket ettiği rahip bir halk olarak kutlar. Vaftiz edilmişler kendilerini ruhsal bir kurban olarak sunarlar; kutsanmış görevliler, Kilise’nin bütün üyelerinin hizmeti için aldıkları Rahiplik Derecesi’ne göre kutlarlar; piskoposlar ve rahipler Baş olan Mesih’in Kişisi’nde hareket ederler." },
      "en": { "q": "How does the Church on earth celebrate the liturgy?",
              "a": "The Church on earth celebrates the liturgy as a priestly people in which each one acts according to his proper function in the unity of the Holy Spirit. The baptized offer themselves in a spiritual sacrifice; the ordained ministers celebrate according to the Order they received for the service of all the members of the Church; the bishops and priests act in the Person of Christ the Head." } },
    { "type": "heading", "level": 5, "id": "liturji-nasil-kutlanir",
      "tr": "Litürji nasıl kutlanır?",
      "en": "How is the liturgy celebrated?" },
    { "type": "qa", "n": 236, "id": "soru-236", "ccc": "1145",
      "tr": { "q": "Litürji nasıl kutlanır?",
              "a": "Litürjinin kutlanması, anlamı yaratılışa ve insan kültürüne kök salmış işaretler ve simgelerle örülüdür. Eski Antlaşma’nın olaylarıyla belirlenir ve Mesih’in Kişisi’nde ve işinde tam olarak açıklanır." },
      "en": { "q": "How is the liturgy celebrated?",
              "a": "The celebration of the liturgy is interwoven with signs and symbols whose meaning is rooted in creation and in human culture. It is determined by the events of the Old Testament and is fully revealed in the Person and work of Christ." } },
    { "type": "qa", "n": 237, "id": "soru-237", "ccc": "1146–1152, 1189",
      "tr": { "q": "Kutsal sır işaretleri nereden gelir?",
              "a": "Bazıları yaratılmış şeylerden gelir (ışık, su, ateş, ekmek, şarap, yağ); bazıları toplumsal yaşamdan gelir (yıkama, meshetme, ekmek bölme). Diğerleri ise Eski Antlaşma’daki kurtuluş tarihinden gelir (Fısıh ayinleri, kurbanlar, ellerin üzerine konması, kutsamalar). Bir kısmı bağlayıcı ve değişmez olan bu işaretler Mesih tarafından benimsenmiş ve O’nun kurtarıcı ve kutsallaştırıcı eyleminin taşıyıcıları kılınmıştır." },
      "en": { "q": "From where do the sacramental signs come?",
              "a": "Some come from created things (light, water, fire, bread, wine, oil); others come from social life (washing, anointing, breaking of bread). Still others come from the history of salvation in the Old Covenant (the Passover rites, the sacrifices, the laying on of hands, the consecrations). These signs, some of which are normative and unchangeable, were taken up by Christ and are made the bearers of his saving and sanctifying action." } },
    { "type": "qa", "n": 238, "id": "soru-238", "ccc": "1153–1155, 1190",
      "tr": { "q": "Kutsal sırların kutlanmasında eylemler ile sözler arasındaki bağ nedir?",
              "a": "Kutsal sırların kutlanmasında eylemler ile sözler birbirine çok sıkı bağlıdır. Gerçekten de simgesel eylemler kendi başlarına zaten bir dil olsalar bile, ayinin sözlerinin bu eylemlere eşlik etmesi ve onlara yaşam vermesi gerekir. Litürjik sözler ve eylemler, hem anlamlı işaretler oldukları hem de işaret ettikleri şeyi gerçekleştirdikleri ölçüde birbirinden ayrılamaz." },
      "en": { "q": "What is the link between the actions and the words in the celebration of the sacraments?",
              "a": "Actions and words are very closely linked in the celebration of the sacraments. Indeed, even if the symbolic actions are already in themselves a language, it is necessary that the words of the rite accompany and give life to these actions. The liturgical words and actions are inseparable both insofar as they are meaningful signs and insofar as they bring about what they signify." } },
    { "type": "qa", "n": 239, "id": "soru-239", "ccc": "1156–1158, 1191",
      "tr": { "q": "Litürjik kutlamalarda ilahi ve müziğin doğru kullanımının ölçütleri nelerdir?",
              "a": "İlahi ve müzik litürjik eylemle sıkı sıkıya bağlı olduğundan şu ölçütlere uymalıdır: Tercihen Kutsal Yazı’dan ve litürjik kaynaklardan alınan metinleri Katolik öğretiye uygun olmalıdır. Duanın güzel bir ifadesi olmalıdır. Müzik yüksek nitelikte olmalıdır. İlahi ve müzik litürjik topluluğun katılımını teşvik etmelidir. Tanrı Halkı’nın kültürel zenginliğini ve kutlamanın kutsal ve görkemli niteliğini ifade etmelidir. “İlahi söyleyen iki kez dua eder” ([[Aziz Augustinus|Saint Augustine]])." },
      "en": { "q": "What are the criteria for the proper use of singing and music in liturgical celebrations?",
              "a": "Since song and music are closely connected with liturgical action they must respect the following criteria. They should conform to Catholic doctrine in their texts, drawn preferably from Sacred Scripture and liturgical sources. They should be a beautiful expression of prayer. The music should be of a high quality. Song and music should encourage the participation of the liturgical assembly. They should express the cultural richness of the People of God and the sacred and solemn character of the celebration. “He who sings, prays twice” (Saint Augustine)." } },
    { "type": "qa", "n": 240, "id": "soru-240", "ccc": "1159–1161, 1192",
      "tr": { "q": "Kutsal tasvirlerin (ikonaların) amacı nedir?",
              "a": "Mesih’in tasviri, <em>en üstün</em> litürjik ikonadır. Diğer tasvirler, Meryem Ana’nın ve Azizlerin betimlemeleri, onlarda yüceltilmiş olan Mesih’i işaret eder. Kutsal Yazı’nın sözle ilettiği aynı Müjde mesajını duyururlar ve inananların imanını uyandırmaya ve beslemeye yardım ederler." },
      "en": { "q": "What is the purpose of holy images?",
              "a": "The image of Christ is the liturgical icon <em>par excellence</em>. Other images, representations of Our Lady and of the Saints, signify Christ who is glorified in them. They proclaim the same Gospel message that Sacred Scripture communicates by the word and they help to awaken and nourish the faith of believers." } },
    { "type": "heading", "level": 5, "id": "liturji-ne-zaman-kutlanir",
      "tr": "Litürji ne zaman kutlanır?",
      "en": "When is the liturgy celebrated?" },
    { "type": "qa", "n": 241, "id": "soru-241", "ccc": "1163–1167, 1193",
      "tr": { "q": "Litürjik zamanın merkezi nedir?",
              "a": "Litürjik zamanın merkezi, bütün litürjik yılın temeli ve çekirdeği olan ve doruğunu bayramların bayramı Paskalya’nın yıllık kutlamasında bulan Pazar günüdür." },
      "en": { "q": "What is the center of the liturgical season?",
              "a": "The center of the liturgical season is Sunday which is the foundation and kernel of the entire liturgical year and has its culmination in the annual celebration of Easter, the feast of feasts." } },
    { "type": "qa", "n": 242, "id": "soru-242", "ccc": "1168–1173, 1194–1195",
      "tr": { "q": "Litürjik yılın işlevi nedir?",
              "a": "Litürjik yılda Kilise, Beden Alma’dan yücelik içinde dönüşüne dek Mesih’in bütün gizemini kutlar. Belirli günlerde Kilise, Tanrı’nın Annesi Kutsal Bakire Meryem’e özel bir sevgiyle saygı gösterir. Kilise ayrıca Mesih için yaşamış, O’nunla birlikte acı çekmiş ve şimdi O’nunla birlikte yücelik içinde yaşayan azizleri anar." },
      "en": { "q": "What is the function of the liturgical year?",
              "a": "In the liturgical year the Church celebrates the whole mystery of Christ from his Incarnation to his return in glory. On set days the Church venerates with special love the Blessed Virgin Mary, the Mother of God. The Church also keeps the memorials of saints who lived for Christ, who suffered with him, and who live with him in glory." } },
    { "type": "qa", "n": 243, "id": "soru-243", "ccc": "1174–1178, 1196",
      "tr": { "q": "Saatlerin Litürjisi nedir?",
              "a": "Kilise’nin kamusal ve ortak duası olan Saatlerin Litürjisi, Mesih’in bedeni olan Kilise ile birlikte yaptığı duadır. Saatlerin Litürjisi aracılığıyla, Efkaristiya’da kutladığımız Mesih’in gizemi, her günün bütününü kutsal kılar ve dönüştürür. Başlıca mezmurlardan, diğer Kutsal Kitap metinlerinden ve Kilise Babaları ile ruhsal ustaların yazılarından alınan okumalardan oluşur." },
      "en": { "q": "What is the Liturgy of the Hours?",
              "a": "The Liturgy of the Hours, which is the public and common prayer of the Church, is the prayer of Christ with his body, the Church. Through the Liturgy of the Hours the mystery of Christ, which we celebrate in the Eucharist, sanctifies and transforms the whole of each day. It is composed mainly of psalms, other biblical texts, and readings from the Fathers and spiritual masters." } },
    { "type": "heading", "level": 5, "id": "liturji-nerede-kutlanir",
      "tr": "Litürji nerede kutlanır?",
      "en": "Where is the liturgy celebrated?" },
    { "type": "qa", "n": 244, "id": "soru-244", "ccc": "1179–1181, 1197–1198",
      "tr": { "q": "Kilise’nin litürjiyi kutlamak için mekânlara ihtiyacı var mı?",
              "a": "Yeni Antlaşma’nın “ruhta ve gerçekte” (Yuhanna 4:24) tapınması hiçbir mekâna tek başına bağlı değildir; çünkü Mesih Tanrı’nın gerçek tapınağıdır. O’nun aracılığıyla Hristiyanlar ve bütün Kilise, Kutsal Ruh’un etkinliğiyle yaşayan Tanrı’nın tapınakları olurlar. Bununla birlikte Tanrı halkı, yeryüzündeki durumunda, topluluğun litürjiyi kutlamak için toplanabileceği mekânlara ihtiyaç duyar." },
      "en": { "q": "Does the Church need places in order to celebrate the liturgy?",
              "a": "The worship “in spirit and truth” (<em>John</em> 4:24) of the New Covenant is not tied exclusively to any place because Christ is the true temple of God. Through him Christians and the whole Church become temples of the living God by the action of the Holy Spirit. Nonetheless, the people of God in their earthly condition need places in which the community can gather to celebrate the liturgy." } },
    { "type": "qa", "n": 245, "id": "soru-245", "ccc": "1181, 1198–1199",
      "tr": { "q": "Kutsal yapılar nedir?",
              "a": "Onlar Tanrı’nın evleridir; o yerde yaşayan Kilise’nin ve göksel [[Kudüs’ün|Jerusalem]] bir simgesidir. Her şeyden önce, Kilise’nin Efkaristiya’yı kutladığı ve tabernakl’da (Kutsal Emanet Dolabı’nda) gerçekten mevcut olan Mesih’e tapındığı dua yerleridir." },
      "en": { "q": "What are sacred buildings?",
              "a": "They are the houses of God, a symbol of the Church that lives in that place as well as of the heavenly Jerusalem. Above all they are places of prayer in which the Church celebrates the Eucharist and worships Christ who is truly present in the tabernacle." } },
    { "type": "qa", "n": 246, "id": "soru-246", "ccc": "1182–1186",
      "tr": { "q": "Kutsal yapıların içindeki ayrıcalıklı yerler hangileridir?",
              "a": "Bunlar şunlardır: sunak, tabernakl, kutsal Krizma’nın (Mürr’ün) ve diğer kutsal yağların saklandığı yer, piskoposun kürsüsü (katedra) ya da rahibin kürsüsü, ambon (okuma kürsüsü), vaftiz kurnası ve günah çıkarma yeri (itiraf odası)." },
      "en": { "q": "What are the privileged places inside sacred buildings?",
              "a": "They are: the altar, the tabernacle, the place where the sacred Chrism and other holy oils are kept, the chair of the bishop (cathedra) or the chair of the priest, the ambo, the baptismal font, and the confessional." } },
    { "type": "heading", "level": 4, "id": "liturjik-cesitlilik-ve-gizemin-birligi",
      "tr": "Litürjik Çeşitlilik ve Gizemin Birliği",
      "en": "Liturgical Diversity and the Unity of the Mystery" },
    { "type": "qa", "n": 247, "id": "soru-247", "ccc": "1200–1204, 1207–1209",
      "tr": { "q": "Mesih’in tek Gizemi Kilise tarafından neden çeşitli litürjik geleneklere göre kutlanır?",
              "a": "Yanıt şudur: Mesih’in gizeminin kavranamaz zenginliği tek bir litürjik gelenekle tüketilemez. Bu nedenle bu zenginlik en başından beri çeşitli halklar ve kültürler arasında harika bir çeşitlilik ve tamamlayıcılıkla belirginleşen biçimlerde ifade buldu." },
      "en": { "q": "Why is the one Mystery of Christ celebrated by the Church according to various liturgical traditions?",
              "a": "The answer is that the unfathomable richness of the mystery of Christ cannot be exhausted by any single liturgical tradition. From the very beginning, therefore, this richness found expression among various peoples and cultures in ways that are characterized by a wonderful diversity and complementarity." } },
    { "type": "qa", "n": 248, "id": "soru-248", "ccc": "1209",
      "tr": { "q": "Çoğulluk içinde birliği güvence altına alan ölçüt nedir?",
              "a": "Bu ölçüt, Havarisel Gelenek’e sadakattir; yani havarilerden alınan iman ve kutsal sırlardaki birliktir. Bu birlik, havarisel ardıllıkla hem işaret edilir hem de güvence altına alınır. Kilise Katolik’tir ve bu nedenle kültürlerin bütün sahih zenginliklerini kendi birliğine katabilir." },
      "en": { "q": "What is the criterion that assures unity in the midst of plurality?",
              "a": "It is fidelity to the Apostolic Tradition, that is, the communion in the faith and in the sacraments received from the apostles, a communion that is both signified and guaranteed by apostolic succession. The Church is Catholic and therefore can integrate into her unity all the authentic riches of cultures." } },
    { "type": "qa", "n": 249, "id": "soru-249", "ccc": "1205–1206",
      "tr": { "q": "Litürjide her şey değişmez midir?",
              "a": "Litürjide, özellikle de kutsal sırların litürjisinde, tanrısal kuruluştan oldukları için değişmez öğeler vardır. Kilise bunların sadık koruyucusudur. Ancak değişebilen öğeler de vardır; Kilise bunları çeşitli halkların kültürlerine uyarlama yetkisine ve zaman zaman da görevine sahiptir." },
      "en": { "q": "Is everything immutable in the liturgy?",
              "a": "In the liturgy, particularly in that of the sacraments, there are unchangeable elements because they are of divine institution. The Church is the faithful guardian of them. There are also, however, elements subject to change which the Church has the power and on occasion also the duty to adapt to the cultures of diverse peoples." } },
    { "type": "heading", "level": 2, "id": "ikinci-bolum-kilisenin-yedi-kutsal-sirri",
      "tr": "İkinci Bölüm: Kilise’nin Yedi Kutsal Sırrı",
      "en": "Section Two: The Seven Sacraments of the Church" },
    { "type": "qa", "n": 250, "id": "soru-250", "ccc": "1210–1211",
      "tr": { "q": "Kilise’nin kutsal sırları nasıl gruplandırılır?",
              "a": "Kutsal sırlar şöyle gruplandırılır: Hristiyanlığa giriş sırları (Vaftiz, Konfirmasyon ve Kutsal Efkaristiya); iyileştirme sırları (Tövbe ve Hastaların Meshedilmesi); ve birliğin ve görevin hizmetindeki sırlar (Kutsal Rahiplik ve Evlilik). Kutsal sırlar Hristiyan yaşamının bütün önemli anlarına dokunur. Bütün kutsal sırlar Kutsal Efkaristiya’ya “amaçlarına yönelir gibi” yönelir ([[Aquinolu Aziz Tomas|Saint Thomas Aquinas]])." },
      "en": { "q": "How are the sacraments of the Church divided?",
              "a": "The sacraments are divided into: the sacraments of Christian initiation (Baptism, Confirmation, and Holy Eucharist); the sacraments of healing (Penance and Anointing of the Sick);, and the sacraments at the service of communion and mission (Holy Orders and Matrimony). The sacraments touch all the important moments of Christian life. All of the sacraments are ordered to the Holy Eucharist “as to their end” (Saint Thomas Aquinas)." } },
    { "type": "heading", "level": 3, "id": "birinci-baslik-hristiyanliga-giris-sirlari",
      "tr": "Birinci Başlık: Hristiyanlığa Giriş Sırları",
      "en": "Chapter One: The sacraments of Christian initiation" },
    { "type": "qa", "n": 251, "id": "soru-251", "ccc": "1212, 1275",
      "tr": { "q": "Hristiyanlığa giriş nasıl gerçekleşir?",
              "a": "Hristiyanlığa giriş, Hristiyan yaşamının <em>temellerini</em> atan kutsal sırlar aracılığıyla gerçekleşir. Vaftizle yeniden doğan inanlılar Konfirmasyon’la güçlendirilir ve ardından Efkaristiya ile beslenirler." },
      "en": { "q": "How is Christian initiation brought about?",
              "a": "Christian initiation is accomplished by means of the sacraments which establish the <em>foundations</em> of Christian life. The faithful born anew by Baptism are strengthened by Confirmation and are then nourished by the Eucharist." } },
    { "type": "heading", "level": 4, "id": "vaftiz-sirri",
      "tr": "Vaftiz Sırrı",
      "en": "The Sacrament of Baptism" },
    { "type": "qa", "n": 252, "id": "soru-252", "ccc": "1213–1216, 1276–1277",
      "tr": { "q": "Hristiyanlığa girişin ilk sırrına hangi adlar verilir?",
              "a": "Bu kutsal sır, kutlanmasındaki merkezi ayin nedeniyle öncelikle <em>Vaftiz</em> diye adlandırılır. Vaftiz etmek, suya “daldırmak” demektir. Vaftiz edilen kişi Mesih’in ölümüne daldırılır ve O’nunla birlikte “yeni bir yaratık” (2 Korintliler 5:17) olarak dirilir. Bu kutsal sıra ayrıca “Kutsal Ruh’ta yeniden doğuşun ve yenilenmenin yıkanması” (Titus 3:5) denir; vaftiz edilen “ışığın çocuğu” (Efesliler 5:8) olduğu için de “aydınlanma” denir." },
      "en": { "q": "What names are given to the first sacrament of initiation?",
              "a": "This sacrament is primarily called <em>Baptism</em> because of the central rite with which it is celebrated. To baptize means to “immerse” in water. The one who is baptized is immersed into the death of Christ and rises with him as a “new creature” (<em>2 Corinthians</em> 5:17). This sacrament is also called the “bath of regeneration and renewal in the Holy Spirit” (<em>Titus</em> 3:5); and it is called “enlightenment” because the baptized becomes “a son of light” (<em>Ephesians</em> 5:8)." } },
    { "type": "qa", "n": 253, "id": "soru-253", "ccc": "1217–1222",
      "tr": { "q": "Vaftiz Eski Antlaşma’da nasıl önceden simgelenmiştir?",
              "a": "Eski Antlaşma’da Vaftiz çeşitli biçimlerde önceden simgelenmiştir: yaşamın ve ölümün kaynağı olarak görülen <em>su</em>; su aracılığıyla kurtaran <em>[[Nuh’un|Noah]] Gemisi</em>; İsrail’i Mısır köleliğinden kurtaran <em>Kızıldeniz’den geçiş</em>; İsrail’i sonsuz yaşamın imgesi olan vaat edilmiş topraklara götüren <em>[[Şeria (Ürdün) Irmağı’ndan|Jordan River]] geçiş</em>." },
      "en": { "q": "How is Baptism prefigured in the Old Covenant?",
              "a": "In the Old Covenant Baptism was pre-figured in various ways: <em>water,</em> seen as source of life and of death; in <em>the Ark of Noah</em>, which saved by means of water; in <em>the passing through the Red Sea, </em>which liberated Israel from Egyptian slavery; in <em>the crossing of the Jordan River, </em>that brought Israel into the promised land which is the image of eternal life." } },
    { "type": "qa", "n": 254, "id": "soru-254", "ccc": "1223–1224",
      "tr": { "q": "Bu öncül simgeleri kim tamamladı?",
              "a": "Eski Antlaşma’nın bütün öncül simgeleri İsa Mesih’te tamamlanır. Kamusal yaşamının başında İsa, Şeria Irmağı’nda [[Vaftizci Yahya|John the Baptist]] tarafından vaftiz edilmeyi kabul etti. Haç üzerinde, delinen böğründen Vaftiz’in ve Efkaristiya’nın işaretleri olan kan ve su aktı. Dirilişinden sonra havarilerine şu görevi verdi: “Gidin, bütün ulusları öğrencilerim olarak yetiştirin; onları Baba, Oğul ve Kutsal Ruh’un adıyla vaftiz edin” (Matta 28:19)." },
      "en": { "q": "Who brought to fulfillment those prefigurations?",
              "a": "All the Old Covenant prefigurations find their fulfillment in Jesus Christ. At the beginning of his public life Jesus had himself baptized by John the Baptist in the Jordan. On the cross, blood and water, signs of Baptism and the Eucharist, flowed from his pierced side. After his Resurrection he gave to his apostles this mission: “Go forth and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit” (<em>Matthew</em> 28:19)." } },
    { "type": "qa", "n": 255, "id": "soru-255", "ccc": "1226–1228",
      "tr": { "q": "Kilise ne zamandan beri ve kime Vaftiz vermiştir?",
              "a": "Kilise, Pentekost gününden beri İsa Mesih’e inanan herkese Vaftiz vermiştir." },
      "en": { "q": "Starting when and to whom has the Church administered Baptism?",
              "a": "From the day of Pentecost, the Church has administered Baptism to anyone who believes in Jesus Christ." } },
    { "type": "qa", "n": 256, "id": "soru-256", "ccc": "1229–1245, 1278",
      "tr": { "q": "Vaftizin temel ayini neden oluşur?",
              "a": "Bu kutsal sırrın temel ayini, Baba’nın, Oğul’un ve Kutsal Ruh’un adı anılırken adayı suya daldırmaktan ya da başına su dökmekten oluşur." },
      "en": { "q": "In what does the essential rite of Baptism consist?",
              "a": "The essential rite of this sacrament consists in immersing the candidate in water or pouring water over his or her head while invoking the name of the Father and the Son and the Holy Spirit." } },
    { "type": "qa", "n": 257, "id": "soru-257", "ccc": "1246–1252",
      "tr": { "q": "Vaftizi kimler alabilir?",
              "a": "Henüz vaftiz edilmemiş her insan Vaftiz alabilir." },
      "en": { "q": "Who can receive Baptism?",
              "a": "Every person not yet baptized is able to receive Baptism." } },
    { "type": "qa", "n": 258, "id": "soru-258", "ccc": "1250",
      "tr": { "q": "Kilise neden bebekleri vaftiz eder?",
              "a": "Kilise bebekleri vaftiz eder, çünkü onlar ilk günahla doğarlar. Kötü Olan’ın gücünden kurtarılmaya ve Tanrı’nın çocuklarına ait olan özgürlük alanına getirilmeye ihtiyaçları vardır." },
      "en": { "q": "Why does the Church baptize infants?",
              "a": "The Church baptizes infants because they are born with original sin. They need to be freed from the power of the Evil One and brought into that realm of freedom which belongs to the children of God." } },
    { "type": "qa", "n": 259, "id": "soru-259", "ccc": "1253–1255",
      "tr": { "q": "Vaftiz edilecek kişiden ne istenir?",
              "a": "Vaftiz edilecek herkesten bir iman ikrarında bulunması istenir. Bu, bir yetişkin söz konusu olduğunda kişisel olarak, bebekler söz konusu olduğunda ise anne babaları ve Kilise tarafından yapılır. Ayrıca vaftiz babası ya da vaftiz annesi ve bütün kilise topluluğu, vaftize hazırlığın (katekümenlik) yanı sıra vaftizde verilen imanın ve lütfun gelişmesi ve korunması sorumluluğunu paylaşırlar." },
      "en": { "q": "What is required of one who is to be baptized?",
              "a": "Everyone who is to be baptized is required to make a profession of faith. This is done personally in the case of an adult or by the parents and by the Church in the case of infants. Also the godfather or the godmother and the whole ecclesial community share the responsibility for baptismal preparation (catechumenate) as well as for the development and safeguarding of the faith and grace given at baptism." } },
    { "type": "qa", "n": 260, "id": "soru-260", "ccc": "1256, 1284",
      "tr": { "q": "Kim vaftiz edebilir?",
              "a": "Vaftizin olağan görevlileri piskopos ve rahiptir. Latin Kilisesi’nde diyakoz da vaftiz edebilir. Zorunluluk durumunda, Kilise’nin yaptığını yapma niyeti taşıması koşuluyla herkes vaftiz edebilir. Bu, adayın başına su dökülerek ve Üçlü Birlik’e dayalı vaftiz formülü söylenerek yapılır: “Seni Baba, Oğul ve Kutsal Ruh’un adıyla vaftiz ediyorum.”" },
      "en": { "q": "Who can baptize?",
              "a": "The ordinary ministers of Baptism are the bishop and the priest. In the Latin Church the deacon also can baptize. In case of necessity any person can baptize provided he has the intention of doing what the Church does. This is done by pouring water on the head of the candidate while saying the Trinitarian formula for Baptism: “I baptize you in the name of the Father and of the Son and of the Holy Spirit”." } },
    { "type": "qa", "n": 261, "id": "soru-261", "ccc": "1257",
      "tr": { "q": "Vaftiz kurtuluş için gerekli midir?",
              "a": "Vaftiz, Müjde’nin kendilerine duyurulduğu ve bu kutsal sırrı isteme olanağı bulmuş olan herkes için kurtuluşa gereklidir." },
      "en": { "q": "Is Baptism necessary for salvation?",
              "a": "Baptism is necessary for salvation for all those to whom the Gospel has been proclaimed and who have had the possibility of asking for this sacrament." } },
    { "type": "qa", "n": 262, "id": "soru-262", "ccc": "1258–1261, 1281–1283",
      "tr": { "q": "Vaftiz olmadan kurtulmak mümkün müdür?",
              "a": "Mesih herkesin kurtuluşu için öldüğünden, iman uğruna ölenler Vaftiz olmadan kurtulabilirler (<em>kan vaftizi</em>). Katekümenler ve Mesih’i ve Kilise’yi tanımasalar bile (lütfun etkisiyle) Tanrı’yı içtenlikle arayan ve O’nun isteğini yerine getirmeye çabalayan herkes de Vaftiz olmadan kurtulabilir (<em>arzu vaftizi</em>). Kilise, litürjisinde vaftiz edilmeden ölen çocukları Tanrı’nın merhametine emanet eder." },
      "en": { "q": "Is it possible to be saved without Baptism?",
              "a": "Since Christ died for the salvation of all, those can be saved without Baptism who die for the faith (<em>Baptism of blood</em>). Catechumens and all those who, even without knowing Christ and the Church, still (under the impulse of grace) sincerely seek God and strive to do his will can also be saved without Baptism (<em>Baptism of desire</em>). The Church in her liturgy entrusts children who die without Baptism to the mercy of God." } },
    { "type": "qa", "n": 263, "id": "soru-263", "ccc": "1262–1274, 1279–1280",
      "tr": { "q": "Vaftizin etkileri nelerdir?",
              "a": "Vaftiz ilk günahı, bütün kişisel günahları ve günahın gerektirdiği bütün cezaları ortadan kaldırır. Vaftiz edilen kişiyi, kişiyi Mesih’e ve Kilisesi’ne katan aklanma lütfu olan kutsallaştırıcı lütuf aracılığıyla Üçlü Birlik’in tanrısal yaşamına ortak kılar. Mesih’in rahipliğine pay verir ve bütün Hristiyanlarla birliğin temelini oluşturur. Tanrısal erdemleri ve Kutsal Ruh’un armağanlarını bağışlar. Vaftiz edilmiş kişi sonsuza dek Mesih’e aittir. Mesih’in silinmez mührüyle (<em>karakter</em>) işaretlenmiştir." },
      "en": { "q": "What are the effects of Baptism?",
              "a": "Baptism takes away original sin, all personal sins and all punishment due to sin. It makes the baptized person a participant in the divine life of the Trinity through sanctifying grace, the grace of justification which incorporates one into Christ and into his Church. It gives one a share in the priesthood of Christ and provides the basis for communion with all Christians. It bestows the theological virtues and the gifts of the Holy Spirit. A baptized person belongs forever to Christ. He is marked with the indelible seal of Christ (<em>character</em>)." } },
    { "type": "qa", "n": 264, "id": "soru-264", "ccc": "2156–2159, 2167",
      "tr": { "q": "Vaftizde alınan Hristiyan adının anlamı nedir?",
              "a": "Ad önemlidir, çünkü Tanrı her birimizi adımızla, yani kişi olarak biricikliğimiz içinde tanır. Vaftizde Hristiyan, Kilise’de kendi adını alır. Bu ad tercihen, vaftiz edilene bir kutsallık örneği ve Tanrı önünde aracılığının güvencesini sunabilecek bir azizin adı olmalıdır." },
      "en": { "q": "What is the meaning of the Christian name received at Baptism?",
              "a": "The name is important because God knows each of us by name, that is, in our uniqueness as persons. In Baptism a Christian receives his or her own name in the Church. It should preferably be the name of a saint who might offer the baptized a model of sanctity and an assurance of his or her intercession before God." } },
    { "type": "heading", "level": 4, "id": "konfirmasyon-guclendirme-sirri",
      "tr": "Konfirmasyon (Güçlendirme) Sırrı",
      "en": "The Sacrament of Confirmation" },
    { "type": "qa", "n": 265, "id": "soru-265", "ccc": "1285–1288, 1315",
      "tr": { "q": "Konfirmasyon Tanrı’nın kurtuluş tasarısında nasıl bir yer tutar?",
              "a": "Eski Antlaşma’da peygamberler Rab’bin Ruhu’nun beklenen Mesih’in ve bütün mesihsel halkın üzerinde duracağını duyurdular. İsa’nın bütün yaşamı ve görevi Kutsal Ruh’la tam bir birlik içinde gerçekleşti. Havariler Pentekost’ta Kutsal Ruh’u aldılar ve “Tanrı’nın büyük işlerini” (Elçilerin İşleri 2:11) duyurdular. Aynı Ruh’un armağanını yeni vaftiz edilenlere ellerini onların üzerine koyarak verdiler. Yüzyıllar boyunca Kilise Ruh’la yaşamaya ve O’nu çocuklarına iletmeye devam etti." },
      "en": { "q": "What place does Confirmation have in the divine plan of salvation?",
              "a": "In the Old Testament the prophets announced that the Spirit of the Lord would rest on the awaited Messiah and on the entire messianic people. The whole life and mission of Jesus were carried out in total communion with the Holy Spirit. The apostles received the Holy Spirit at Pentecost and proclaimed “the great works of God” (<em>Acts</em> 2:11). They gave the gift of the same Spirit to the newly baptized by the laying on of hands. Down through the centuries, the Church has continued to live by the Spirit and to impart him to her children." } },
    { "type": "qa", "n": 266, "id": "soru-266", "ccc": "1289",
      "tr": { "q": "Bu kutsal sırra neden <em>Krizmasyon</em> ya da <em>Konfirmasyon</em> denir?",
              "a": "Ona <em>Krizmasyon</em> (Doğu Kiliselerinde: kutsal mürr ya da krizma ile meshetme) denir, çünkü bu kutsal sırrın temel ayini krizma ile meshetmedir. <em>Konfirmasyon</em> (Güçlendirme) denir, çünkü vaftiz lütfunu doğrular ve güçlendirir." },
      "en": { "q": "Why is this sacrament called <em>Chrismation</em> or <em>Confirmation</em>?",
              "a": "It is called <em>Chrismation</em> (in the Eastern Churches: Anointing with holy myron or chrism) because the essential rite of the sacrament is anointing with chrism. It is called <em>Confirmation</em> because it confirms and strengthens baptismal grace." } },
    { "type": "qa", "n": 267, "id": "soru-267", "ccc": "1290–1301, 1318, 1320–1321",
      "tr": { "q": "Konfirmasyon’un temel ayini nedir?",
              "a": "Konfirmasyon’un temel ayini, kutsal Krizma (balsamla karıştırılmış ve piskopos tarafından kutsanmış yağ) ile meshetmedir; bu, ayine özgü kutsal sır sözlerini söyleyen görevlinin elini koymasıyla yapılır. Batı’da bu meshetme vaftiz edilmişin alnına şu sözlerle yapılır: “Kutsal Ruh’un armağanıyla mühürlen.” Bizans ayinli Doğu Kiliselerinde bu meshetme bedenin başka yerlerine de şu sözlerle yapılır: “Kutsal Ruh armağanının mührü.”" },
      "en": { "q": "What is the essential rite of Confirmation?",
              "a": "The essential rite of Confirmation is the anointing with Sacred Chrism (oil mixed with balsam and consecrated by the bishop), which is done by the laying on of the hand of the minister who pronounces the sacramental words proper to the rite. In the West this anointing is done on the forehead of the baptized with the words, “Be sealed with the gift of the Holy Spirit”. In the Eastern Churches of the Byzantine rite this anointing is also done on other parts of the body with the words, “The seal of the gift of the Holy Spirit”." } },
    { "type": "qa", "n": 268, "id": "soru-268", "ccc": "1302–1305, 1316–1317",
      "tr": { "q": "Konfirmasyon’un etkisi nedir?",
              "a": "Konfirmasyon’un etkisi, Pentekost’takine benzer özel bir Kutsal Ruh dökülmesidir. Bu dökülme cana silinmez bir mühür basar ve Vaftiz lütfunda bir büyüme sağlar. Alan kişiyi tanrısal oğullukta daha derinden köklendirir, onu Mesih’e ve Kilise’ye daha sıkı bağlar ve Kutsal Ruh’un armağanlarını canında yeniden canlandırır. Hristiyan imanına tanıklık etmek için özel bir güç verir." },
      "en": { "q": "What is the effect of Confirmation?",
              "a": "The effect of Confirmation is a special outpouring of the Holy Spirit like that of Pentecost. This outpouring impresses on the soul an indelible character and produces a growth in the grace of Baptism. It roots the recipient more deeply in divine sonship, binds him more firmly to Christ and to the Church and reinvigorates the gifts of the Holy Spirit in his soul. It gives a special strength to witness to the Christian faith." } },
    { "type": "qa", "n": 269, "id": "soru-269", "ccc": "1306–1311, 1319",
      "tr": { "q": "Bu kutsal sırrı kimler alabilir?",
              "a": "Yalnızca bir kez alınabilen bu kutsal sırrı, yalnızca daha önce vaftiz edilmiş olanlar alabilir ve almalıdır. Konfirmasyon’u etkili biçimde alabilmek için adayın lütuf durumunda olması gerekir." },
      "en": { "q": "Who can receive this sacrament?",
              "a": "Only those already baptized can and should receive this sacrament which can be received only once. To receive Confirmation efficaciously the candidate must be in the state of grace." } },
    { "type": "qa", "n": 270, "id": "soru-270", "ccc": "1312–1314",
      "tr": { "q": "Konfirmasyon’un görevlisi kimdir?",
              "a": "Konfirmasyon’un asıl görevlisi piskopostur. Böylece konfirmasyon alan kişi ile Kilise’nin havarisel boyutu arasındaki bağ görünür kılınır. Bir rahip bu kutsal sırrı verdiğinde –Doğu’da olağan olarak, Batı’da ise özel durumlarda olduğu gibi– piskoposla ve Kilise’yle bağ, piskoposun yardımcısı olan rahip ve piskoposun kendisi tarafından kutsanmış kutsal Krizma aracılığıyla ifade edilir." },
      "en": { "q": "Who is the minister of Confirmation?",
              "a": "The original minister of Confirmation is the bishop. In this way the link between the confirmed and the Church in her apostolic dimension is made manifest. When a priest confers this sacrament, as ordinarily happens in the East and in special cases in the West, the link with the bishop and with the Church is expressed by the priest who is the collaborator of the bishop and by the Sacred Chrism, consecrated by the bishop himself." } },
    { "type": "heading", "level": 4, "id": "efkaristiya-sirri",
      "tr": "Efkaristiya Sırrı",
      "en": "The Sacrament of the Eucharist" },
    { "type": "qa", "n": 271, "id": "soru-271", "ccc": "1322–1323, 1409",
      "tr": { "q": "Efkaristiya nedir?",
              "a": "Efkaristiya, Rab İsa’nın haç kurbanını yücelik içinde dönüşüne dek çağlar boyunca sürdürmek için kurduğu, O’nun Bedeninin ve Kanının kurbanının ta kendisidir. Böylece ölümünün ve Dirilişinin bu anmasını Kilisesi’ne emanet etti. Efkaristiya birliğin işareti, sevginin bağı ve Paskalya şölenidir; bu şölende Mesih yenir, akıl lütufla dolar ve bize gelecekteki yüceliğin bir rehini verilir." },
      "en": { "q": "What is the Eucharist?",
              "a": "The Eucharist is the very sacrifice of the Body and Blood of the Lord Jesus which he instituted to perpetuate the sacrifice of the cross throughout the ages until his return in glory. Thus he entrusted to his Church this memorial of his death and Resurrection. It is a sign of unity, a bond of charity, a paschal banquet, in which Christ is consumed, the mind is filled with grace, and a pledge of future glory is given to us." } },
    { "type": "qa", "n": 272, "id": "soru-272", "ccc": "1323, 1337–1340",
      "tr": { "q": "İsa Mesih Efkaristiya’yı ne zaman kurdu?",
              "a": "İsa Efkaristiya’yı Kutsal Perşembe günü, “ele verildiği gece” (1 Korintliler 11:23), havarileriyle Son Akşam Yemeği’ni kutlarken kurdu." },
      "en": { "q": "When did Jesus Christ institute the Eucharist?",
              "a": "Jesus instituted the Eucharist on Holy Thursday “the night on which he was betrayed” (<em>1 Corinthians</em> 11:23), as he celebrated the Last Supper with his apostles." } },
    { "type": "qa", "n": 273, "id": "soru-273", "ccc": "1337–1340, 1365, 1406",
      "tr": { "q": "Efkaristiya’yı nasıl kurdu?",
              "a": "İsa havarileriyle birlikte Yukarı Oda’da (Senakl) toplandıktan sonra eline ekmeği aldı. Onu böldü ve onlara vererek şöyle dedi: “Hepiniz alın ve bundan yiyin; bu, sizin için feda edilecek olan Bedenimdir.” Sonra şarap kâsesini eline aldı ve şöyle dedi: “Hepiniz alın ve bundan için. Bu, Kanımın kâsesidir, yeni ve sonsuz antlaşmanın Kanı. Günahlar bağışlansın diye sizin ve herkes için dökülecektir. Bunu beni anmak için yapın.”" },
      "en": { "q": "How did he institute the Eucharist?",
              "a": "After he had gathered with his apostles in the Cenacle, Jesus took bread in his hands. He broke it and gave it to them saying, “Take this and eat it, all of you; this is my Body which will be given up for you”. Then, he took the cup of wine in his hands and said, “Take this and drink of this, all of you. This is the cup of my Blood, the Blood of the new and everlasting covenant. It will be shed for you and for all so that sins may be forgive. Do this in memory of me”." } },
    { "type": "qa", "n": 274, "id": "soru-274", "ccc": "1324–1327, 1407",
      "tr": { "q": "Efkaristiya Kilise’nin yaşamında neyi temsil eder?",
              "a": "Efkaristiya bütün Hristiyan yaşamının kaynağı ve doruğudur. Efkaristiya’da, Tanrı’nın bize yönelik kutsallaştırıcı eylemi ve bizim O’na tapınmamız en yüksek noktalarına ulaşır. Kilise’nin bütün ruhsal hazinesini, Mesih’in Kendisini, Paskalyamızı içerir. Tanrısal yaşamla birlik ve Tanrı Halkı’nın birliği Efkaristiya aracılığıyla hem ifade edilir hem de gerçekleştirilir. Efkaristiya kutlaması aracılığıyla göksel litürjiyle şimdiden birleşiriz ve sonsuz yaşamın önden tadını alırız." },
      "en": { "q": "What does the Eucharist represent in the life of the Church?",
              "a": "It is the source and summit of all Christian life. In the Eucharist, the sanctifying action of God in our regard and our worship of him reach their high point. It contains the whole spiritual good of the Church, Christ himself, our Pasch. Communion with divine life and the unity of the People of God are both expressed and effected by the Eucharist. Through the eucharistic celebration we are united already with the liturgy of heaven and we have a foretaste of eternal life." } },
    { "type": "qa", "n": 275, "id": "soru-275", "ccc": "1328–1332",
      "tr": { "q": "Bu kutsal sırrın adları nelerdir?",
              "a": "Bu kutsal sırrın kavranamaz zenginliği, onun çeşitli yönlerini çağrıştıran farklı adlarla ifade edilir. En yaygın adlar şunlardır: Efkaristiya, Kutsal Ayin (Missa), Rab’bin Sofrası, Ekmeğin Bölünmesi, Efkaristiya Kutlaması, Rab’bin çilesinin, ölümünün ve Dirilişinin Anması, Kutsal Kurban, Kutsal ve Tanrısal Litürji, Kutsal Gizemler, Sunağın En Kutsal Sırrı ve Kutsal Komünyon." },
      "en": { "q": "What are the names for this sacrament?",
              "a": "The unfathomable richness of this sacrament is expressed in different names which evoke its various aspects. The most common names are: the Eucharist, Holy Mass, the Lord’s Supper, the Breaking of the Bread, the Eucharistic Celebration, the Memorial of the passion, death and Resurrection of the Lord, the Holy Sacrifice, the Holy and Divine Liturgy, the Sacred Mysteries, the Most Holy Sacrament of the Altar, and Holy Communion." } },
    { "type": "qa", "n": 276, "id": "soru-276", "ccc": "1333–1344",
      "tr": { "q": "Efkaristiya Tanrı’nın kurtuluş tasarısında nereye oturur?",
              "a": "Efkaristiya Eski Antlaşma’da, her şeyden önce Yahudilerin [[Mısır’dan|Egypt]] aceleyle ve özgürleştirici çıkışlarını anmak için her yıl mayasız ekmekle kutladıkları yıllık Fısıh (Pesah) yemeğinde önceden simgelenmişti. İsa onu öğretisinde önceden bildirdi ve havarileriyle birlikte bir Fısıh yemeğinde Son Akşam Yemeği’ni kutlarken kurdu. Rabbinin “Bunu beni anmak için yapın” (1 Korintliler 11:24) buyruğuna sadık kalan Kilise, Efkaristiya’yı her zaman, özellikle de İsa’nın Dirilişi’nin günü olan Pazar günü kutlamıştır." },
      "en": { "q": "Where does the Eucharist fit in the divine plan of salvation?",
              "a": "The Eucharist was foreshadowed in the Old Covenant above all in the annual Passover meal celebrated every year by the Jews with unleavened bread to commemorate their hasty, liberating departure from Egypt. Jesus foretold it in his teaching and he instituted it when he celebrated the Last Supper with his apostles in a Passover meal. The Church, faithful to the command of her Lord, “Do this in memory of me” (<em>1 Corinthians</em> 11:24), has always celebrated the Eucharist, especially on Sunday, the day of the Resurrection of Jesus." } },
    { "type": "qa", "n": 277, "id": "soru-277", "ccc": "1345–1355, 1408",
      "tr": { "q": "Kutsal Efkaristiya’nın kutlanması nasıl gerçekleşir?",
              "a": "Efkaristiya, birlikte tek bir tapınma eylemi oluşturan iki büyük bölümden oluşur. Söz Litürjisi, Tanrı Sözü’nün duyurulmasını ve dinlenmesini içerir. Efkaristiya Litürjisi ise ekmeğin ve şarabın sunulmasını, kutsama sözlerini içeren duayı ya da anaforayı ve komünyonu içerir." },
      "en": { "q": "How is the celebration of the Holy Eucharist carried out?",
              "a": "The Eucharist unfolds in two great parts which together form one, single act of worship. The Liturgy of the Word involves proclaiming and listening to the Word of God. The Liturgy of the Eucharist includes the presentation of the bread and wine, the prayer or the anaphora containing the words of consecration, and communion." } },
    { "type": "qa", "n": 278, "id": "soru-278", "ccc": "1348, 1411",
      "tr": { "q": "Efkaristiya’nın kutlanmasının görevlisi kimdir?",
              "a": "Efkaristiya’yı kutlayan, Baş olan Mesih’in Kişisi’nde ve Kilise’nin adına hareket eden, geçerli biçimde kutsanmış bir rahiptir (piskopos ya da rahip)." },
      "en": { "q": "Who is the minister for the celebration of the Eucharist?",
              "a": "The celebrant of the Eucharist is a validly ordained priest (bishop or priest) who acts in the Person of Christ the Head and in the name of the Church." } },
    { "type": "qa", "n": 279, "id": "soru-279", "ccc": "1412",
      "tr": { "q": "Efkaristiya’yı kutlamak için temel ve gerekli öğeler nelerdir?",
              "a": "Temel öğeler buğday ekmeği ve üzüm şarabıdır." },
      "en": { "q": "What are the essential and necessary elements for celebrating the Eucharist?",
              "a": "The essential elements are wheat bread and grape wine." } },
    { "type": "qa", "n": 280, "id": "soru-280", "ccc": "1362–1367",
      "tr": { "q": "Efkaristiya hangi anlamda Mesih’in kurbanının <em>anmasıdır</em>?",
              "a": "Efkaristiya, Mesih’in insanlık adına haç üzerinde bir kez ve sonsuza dek Baba’ya sunduğu kurbanı mevcut ve güncel kıldığı anlamında bir <em>anmadır</em>. Kutsal Efkaristiya’nın kurban niteliği, kuruluş sözlerinin kendisinde görünür: “Bu, sizin için feda edilen Bedenimdir” ve “Bu kâse, sizin için dökülecek olan kanımla yapılan Yeni Antlaşma’dır” (Luka 22:19-20). Haç kurbanı ile Efkaristiya kurbanı <em>tek ve aynı kurbandır</em>. Sunan rahip ve kurban edilen aynıdır; yalnızca sunuluş biçimi farklıdır: haçta kanlı bir biçimde, Efkaristiya’da kansız bir biçimde." },
      "en": { "q": "In what way is the Eucharist a <em>memorial</em> of the sacrifice of Christ?",
              "a": "The Eucharist is a <em>memorial</em> in the sense that it makes present and actual the sacrifice which Christ offered to the Father on the cross, once and for all on behalf of mankind. The sacrificial character of the Holy Eucharist is manifested in the very words of institution, “This is my Body which is given for you” and “This cup is the New Covenant in my Blood that will be shed for you” (Luke 22:19-20). The sacrifice of the cross and the sacrifice of the Eucharist are <em>one and the same sacrifice</em>. The priest and the victim are the same; only the manner of offering is different: in a bloody manner on the cross, in an unbloody manner in the Eucharist." } },
    { "type": "qa", "n": 281, "id": "soru-281", "ccc": "1368–1372, 1414",
      "tr": { "q": "Kilise Efkaristiya kurbanına nasıl katılır?",
              "a": "Efkaristiya’da Mesih’in kurbanı, O’nun Bedeninin üyelerinin de kurbanı olur. İnanlıların yaşamları, övgüleri, acıları, duaları ve çalışmaları Mesih’inkilerle birleşir. Bir kurban olduğu ölçüde Efkaristiya, herkesin günahlarının bedeli olarak ve Tanrı’dan ruhsal ve dünyasal yararlar elde etmek için dirisiyle ölüsüyle bütün inanlılar için de sunulur. Göksel Kilise de Mesih’in sunusuyla birleşir." },
      "en": { "q": "In what way does the Church participate in the eucharistic sacrifice?",
              "a": "In the Eucharist the sacrifice of Christ becomes also the sacrifice of the members of his Body. The lives of the faithful, their praise, their suffering, their prayers, their work, are united to those of Christ. In as much as it is a sacrifice, the Eucharist is likewise offered for all the faithful, living and dead, in reparation for the sins of all and to obtain spiritual and temporal benefits from God. The Church in heaven is also united to the offering of Christ." } },
    { "type": "qa", "n": 282, "id": "soru-282", "ccc": "1373–1375, 1413",
      "tr": { "q": "Mesih Efkaristiya’da nasıl mevcuttur?",
              "a": "İsa Mesih Efkaristiya’da eşsiz ve kıyaslanamaz bir biçimde mevcuttur. Bedeniyle ve Kanıyla, Canıyla ve Tanrılığıyla gerçek, somut ve özsel bir biçimde mevcuttur. Bu nedenle Efkaristiya’da, kutsal sır biçiminde, yani ekmeğin ve şarabın Efkaristiya görünümleri altında, Tanrı ve İnsan olan Mesih bütünüyle ve tamamıyla mevcuttur." },
      "en": { "q": "How is Christ present in the Eucharist?",
              "a": "Jesus Christ is present in the Eucharist in a unique and incomparable way. He is present in a true, real and substantial way, with his Body and his Blood, with his Soul and his Divinity. In the Eucharist, therefore, there is present in a sacramental way, that is, under the Eucharistic species of bread and wine, Christ whole and entire, God and Man." } },
    { "type": "qa", "n": 283, "id": "soru-283", "ccc": "1376–1377, 1413",
      "tr": { "q": "<em>Özdönüşüm</em> (transsubstantiatio) ne anlama gelir?",
              "a": "<em>Özdönüşüm</em>, ekmeğin bütün özünün Mesih’in Bedeninin özüne ve şarabın bütün özünün O’nun Kanının özüne dönüşmesi anlamına gelir. Bu dönüşüm, Efkaristiya duasında Mesih’in sözünün etkinliği ve Kutsal Ruh’un eylemiyle gerçekleşir. Ancak ekmeğin ve şarabın dış özellikleri, yani “Efkaristiya görünümleri” değişmeden kalır." },
      "en": { "q": "What is the meaning of <em>transubstantiation</em>?",
              "a": "<em>Transubstantiation</em> means the change of the whole substance of bread into the substance of the Body of Christ and of the whole substance of wine into the substance of his Blood. This change is brought about in the eucharistic prayer through the efficacy of the word of Christ and by the action of the Holy Spirit. However, the outward characteristics of bread and wine, that is the “eucharistic species”, remain unaltered." } },
    { "type": "qa", "n": 284, "id": "soru-284", "ccc": "1377",
      "tr": { "q": "Ekmeğin bölünmesi Mesih’i böler mi?",
              "a": "Ekmeğin bölünmesi Mesih’i bölmez. O, Efkaristiya görünümlerinin her birinde ve bunların her parçasında bütünüyle ve tamamıyla mevcuttur." },
      "en": { "q": "Does the breaking of the bread divide Christ?",
              "a": "The breaking of the bread does not divide Christ. He is present whole and entire in each of the eucharistic species and in each of their parts." } },
    { "type": "qa", "n": 285, "id": "soru-285", "ccc": "1377",
      "tr": { "q": "Mesih’in Efkaristiya’daki varlığı ne kadar sürer?",
              "a": "Mesih’in Efkaristiya’daki varlığı, Efkaristiya görünümleri var oldukça sürer." },
      "en": { "q": "How long does the presence of Christ last in the Eucharist?",
              "a": "The presence of Christ continues in the Eucharist as long as the eucharistic species subsist." } },
    { "type": "qa", "n": 286, "id": "soru-286", "ccc": "1378–1381, 1418",
      "tr": { "q": "Efkaristiya sırrına nasıl bir tapınma gösterilmelidir?",
              "a": "Efkaristiya sırrına, ister Ayin kutlaması sırasında ister onun dışında olsun, <em>latreia</em> tapınması, yani yalnızca Tanrı’ya sunulan tapınma gösterilmelidir. Kilise kutsanmış Hostiyaları (kutsal ekmekleri) en büyük özenle korur. Onları hastalara ve Ayin’e katılamayan diğer kişilere götürür. Onları inanlıların görkemli tapınmasına sunar ve tören alaylarında taşır. Kilise, inanlıları tabernaklda saklanan En Kutsal Sır’ra tapınmak için sık sık ziyarette bulunmaya teşvik eder." },
      "en": { "q": "What kind of worship is due to the sacrament of the Eucharist?",
              "a": "The worship due to the sacrament of the Eucharist, whether during the celebration of the Mass or outside it, is the worship of <em>latria</em>, that is, the adoration given to God alone. The Church guards with the greatest care Hosts that have been consecrated. She brings them to the sick and to other persons who find it impossible to participate at Mass. She also presents them for the solemn adoration of the faithful and she bears them in processions. The Church encourages the faithful to make frequent visits to adore the Blessed Sacrament reserved in the tabernacle." } },
    { "type": "qa", "n": 287, "id": "soru-287", "ccc": "1382–1384, 1391–1396",
      "tr": { "q": "Kutsal Efkaristiya neden Paskalya şölenidir?",
              "a": "Kutsal Efkaristiya Paskalya şölenidir; çünkü Mesih onda Kendi Paskalyasını kutsal sır biçiminde mevcut kılar ve bize yiyecek ve içecek olarak sunulan Bedenini ve Kanını verir; bizi kurbanında Kendisiyle ve birbirimizle birleştirir." },
      "en": { "q": "Why is the Holy Eucharist the paschal banquet?",
              "a": "The Holy Eucharist is the paschal banquet in as much as Christ sacramentally makes present his Passover and gives us his Body and Blood, offered as food and drink, uniting us to himself and to one another in his sacrifice." } },
    { "type": "qa", "n": 288, "id": "soru-288", "ccc": "1383, 1410",
      "tr": { "q": "Sunağın anlamı nedir?",
              "a": "<em>Sunak</em>, hem kurban (kurban sunağı) hem de bize verilen göksel yiyecek (Rab’bin sofrası) olarak mevcut olan Mesih’in Kendisinin simgesidir." },
      "en": { "q": "What is the meaning of the altar?",
              "a": "The <em>altar</em> is the symbol of Christ himself who is present both as sacrificial victim (the altar of the sacrifice) and as food from heaven which is given to us (the table of the Lord)." } },
    { "type": "qa", "n": 289, "id": "soru-289", "ccc": "1389, 1417",
      "tr": { "q": "Kilise üyelerini ne zaman Kutsal Ayin’e katılmakla yükümlü tutar?",
              "a": "Kilise inanlıları her Pazar günü ve zorunlu kutsal bayram günlerinde Kutsal Ayin’e katılmakla yükümlü tutar. Diğer günlerde de Kutsal Ayin’e katılmayı tavsiye eder." },
      "en": { "q": "When does the Church oblige her members to participate at Holy Mass?",
              "a": "The Church obliges the faithful to participate at Holy Mass every Sunday and on holy days of obligation. She recommends participation at Holy Mass on other days as well." } },
    { "type": "qa", "n": 290, "id": "soru-290", "ccc": "1389",
      "tr": { "q": "Kutsal Komünyon ne zaman alınmalıdır?",
              "a": "Kilise, inanlıların gerekli iç hazırlığa sahiplerse Kutsal Ayin’e her katıldıklarında Kutsal Komünyon almalarını tavsiye eder. Ancak Kilise onları en az yılda bir kez, Paskalya döneminde Kutsal Komünyon almakla yükümlü tutar." },
      "en": { "q": "When must one receive Holy Communion?",
              "a": "The Church recommends that the faithful, if they have the required dispositions, receive Holy Communion whenever they participate at Holy Mass. However, the Church obliges them to receive Holy Communion at least once a year during the Easter season." } },
    { "type": "qa", "n": 291, "id": "soru-291", "ccc": "1385–1389, 1415",
      "tr": { "q": "Kutsal Komünyon almak için ne gereklidir?",
              "a": "Kutsal Komünyon alabilmek için kişi Katolik Kilisesi’ne tam olarak katılmış olmalı ve lütuf durumunda, yani ölümcül bir günah içinde olduğunun bilincinde olmamalıdır. Ağır bir günah işlediğinin bilincinde olan herkes komünyona gitmeden önce Barışma sırrını almalıdır. Kutsal Komünyon alanlar için ayrıca bir iç toplanma ve dua ruhu, Kilise’nin öngördüğü oruca uyulması ve Mesih’e saygının bir işareti olarak bedenin uygun tutumu (davranışlar ve giyim) önemlidir." },
      "en": { "q": "What is required to receive Holy Communion?",
              "a": "To receive Holy Communion one must be fully incorporated into the Catholic Church and be in the state of grace, that is, not conscious of being in mortal sin. Anyone who is conscious of having committed a grave sin must first receive the sacrament of Reconciliation before going to Communion. Also important for those receiving Holy Communion are a spirit of recollection and prayer, observance of the fast prescribed by the Church, and an appropriate disposition of the body (gestures and dress) as a sign of respect for Christ." } },
    { "type": "qa", "n": 292, "id": "soru-292", "ccc": "1391–1397, 1416",
      "tr": { "q": "Kutsal Komünyon’un meyveleri nelerdir?",
              "a": "Kutsal Komünyon Mesih’le ve O’nun Kilisesi’yle birliğimizi artırır. Vaftiz ve Konfirmasyon’da alınan lütuf yaşamını korur ve yeniler; komşumuza olan sevgimizde büyümemizi sağlar. Bizi sevgide güçlendirir, hafif günahları siler ve bizi gelecekte ölümcül günahtan korur." },
      "en": { "q": "What are the fruits of Holy Communion?",
              "a": "Holy Communion increases our union with Christ and with his Church. It preserves and renews the life of grace received at Baptism and Confirmation and makes us grow in love for our neighbor. It strengthens us in charity, wipes away venial sins and preserves us from mortal sin in the future." } },
    { "type": "qa", "n": 293, "id": "soru-293", "ccc": "1398–1401",
      "tr": { "q": "Diğer Hristiyanlara Kutsal Komünyon vermek ne zaman mümkündür?",
              "a": "Katolik görevliler, Katolik Kilisesi ile tam birlik içinde olmayan Doğu Kiliselerinin üyelerine, kendi istekleriyle istediklerinde ve gerekli iç hazırlığa sahip olduklarında Kutsal Komünyon’u meşru olarak verebilirler. Katolik görevliler diğer kilise topluluklarının üyelerine ise ancak ağır bir zorunluluk durumunda, kendi istekleriyle istediklerinde, gerekli iç hazırlığa sahip olduklarında ve bu kutsal sırla ilgili Katolik imanı taşıdıklarını gösterdiklerinde Kutsal Komünyon’u meşru olarak verebilirler." },
      "en": { "q": "When is it possible to give Holy Communion to other Christians?",
              "a": "Catholic ministers may give Holy Communion licitly to members of the Oriental Churches which are not in full communion with the Catholic Church whenever they ask for it of their own will and possess the required dispositions. Catholic ministers may licitly give Holy Communion to members of other ecclesial communities only if, in grave necessity, they ask for it of their own will, possess the required dispositions, and give evidence of holding the Catholic faith regarding the sacrament." } },
    { "type": "qa", "n": 294, "id": "soru-294", "ccc": "1402–1405",
      "tr": { "q": "Efkaristiya neden “gelecekteki yüceliğin rehini”dir?",
              "a": "Efkaristiya gelecekteki yüceliğin rehinidir; çünkü bizi her türlü lütuf ve göksel nimetle doldurur. Bu yaşamdaki hac yolculuğumuz için bizi güçlendirir ve sonsuz yaşamı özlememizi sağlar. Bizi şimdiden Baba’nın sağında oturan Mesih’le, göksel Kilise’yle, Kutsal Bakire ve bütün azizlerle birleştirir." },
      "en": { "q": "Why is the Eucharist a “pledge of future glory”?",
              "a": "The Eucharist is a pledge of future glory because it fills us with every grace and heavenly blessing. It fortifies us for our pilgrimage in this life and makes us long for eternal life. It unites us already to Christ seated at the right hand of the Father, to the Church in heaven and to the Blessed Virgin and all the saints." } },
    { "type": "quote",
      "tr": "Efkaristiya’da “ölümsüzlüğün ilacını, ölüme karşı panzehiri ve bizi İsa Mesih’te sonsuza dek yaşatan yiyeceği sağlayan tek ekmeği böleriz.” ([[Antakyalı Aziz İgnatius|Saint Ignatius of Antioch]])",
      "en": "In the Eucharist, we “break the one bread that provides the medicine of immortality, the antidote for death and the food that makes us live forever in Jesus Christ.” (Saint Ignatius of Antioch)" },
    { "type": "heading", "level": 3, "id": "ikinci-baslik-iyilestirme-sirlari",
      "tr": "İkinci Başlık: İyileştirme Sırları",
      "en": "Chapter Two: The Sacraments of Healing" },
    { "type": "qa", "n": 295, "id": "soru-295", "ccc": "1420–1421, 1426",
      "tr": { "q": "Mesih neden Tövbe ve Hastaların Meshedilmesi sırlarını kurdu?",
              "a": "Canımızın ve bedenimizin hekimi olan Mesih bu kutsal sırları kurdu; çünkü Hristiyanlığa giriş sırlarında bize verdiği yeni yaşam günah yüzünden zayıflayabilir, hatta yitirilebilir. Bu nedenle Mesih, Kilisesi’nin bu iki kutsal sır aracılığıyla O’nun iyileştirme ve kurtarma işini sürdürmesini istedi." },
      "en": { "q": "Why did Christ institute the sacraments of Penance and the Anointing of the Sick?",
              "a": "Christ, the physician of our soul and body, instituted these sacraments because the new life that he gives us in the sacraments of Christian initiation can be weakened and even lost because of sin. Therefore, Christ willed that his Church should continue his work of healing and salvation by means of these two sacraments." } },
    { "type": "heading", "level": 4, "id": "tovbe-ve-barisma-sirri",
      "tr": "Tövbe ve Barışma Sırrı",
      "en": "The Sacrament of Penance and Reconciliation" },
    { "type": "qa", "n": 296, "id": "soru-296", "ccc": "1422–1424",
      "tr": { "q": "Bu kutsal sırrın adı nedir?",
              "a": "Ona Tövbe sırrı, Barışma sırrı, Bağışlanma sırrı, İtiraf (Günah Çıkarma) sırrı ve Dönüşüm sırrı denir." },
      "en": { "q": "What is the name of this sacrament?",
              "a": "It is called the sacrament of Penance, the sacrament of Reconciliation, the sacrament of Forgiveness, the sacrament of Confession, and the sacrament of Conversion." } },
    { "type": "qa", "n": 297, "id": "soru-297", "ccc": "1425–1426, 1484",
      "tr": { "q": "Vaftizden sonra neden bir Barışma sırrı vardır?",
              "a": "Vaftizde alınan yeni lütuf yaşamı insan doğasının zayıflığını ve günaha eğilimi (yani <em>şehvet eğilimini</em>) ortadan kaldırmadığı için, Mesih bu kutsal sırrı günah yüzünden O’ndan ayrılmış olan vaftiz edilmişlerin tövbesi için kurdu." },
      "en": { "q": "Why is there a sacrament of Reconciliation after Baptism?",
              "a": "Since the new life of grace received in Baptism does not abolish the weakness of human nature nor the inclination to sin (that is, <em>concupiscence</em>), Christ instituted this sacrament for the conversion of the baptized who have been separated from him by sin." } },
    { "type": "qa", "n": 298, "id": "soru-298", "ccc": "1485",
      "tr": { "q": "Bu kutsal sırrı ne zaman kurdu?",
              "a": "Dirilen Rab bu kutsal sırrı Paskalya akşamı, havarilerine göründüğünde ve onlara şöyle dediğinde kurdu: “Kutsal Ruh’u alın. Kimin günahlarını bağışlarsanız, bağışlanmış olur; kimin günahlarını bağışlamazsanız, bağışlanmamış olur” (Yuhanna 20:22-23)." },
      "en": { "q": "When did he institute this sacrament?",
              "a": "The risen Lord instituted this sacrament on the evening of Easter when he showed himself to his apostles and said to them, “Receive the Holy Spirit. If you forgive the sins of any, they are forgiven; if you retain the sins of any, they are retained.” (<em>John</em> 20:22-23)." } },
    { "type": "qa", "n": 299, "id": "soru-299", "ccc": "1427–1429",
      "tr": { "q": "Vaftiz edilmişlerin tövbeye ihtiyacı var mı?",
              "a": "Mesih’in tövbe çağrısı vaftiz edilmişlerin yaşamında yankılanmaya devam eder. Tövbe (dönüşüm), bütün Kilise için sürekli bir yükümlülüktür. Kilise kutsaldır, ama kendi içinde günahkârları da barındırır." },
      "en": { "q": "Do the baptized have need of conversion?",
              "a": "The call of Christ to conversion continues to resound in the lives of the baptized. Conversion is a continuing obligation for the whole Church. She is holy but includes sinners in her midst." } },
    { "type": "qa", "n": 300, "id": "soru-300", "ccc": "1430–1433, 1490",
      "tr": { "q": "İç tövbe nedir?",
              "a": "İç tövbe, tanrısal lütfun Tanrı’nın merhametli sevgisine yanıt vermeye çektiği “pişman bir yüreğin” (Mezmurlar 51:19) hareketidir. Bu, işlenmiş günahlar için üzüntüyü ve onlardan tiksinmeyi, gelecekte bir daha günah işlememeye sağlam bir kararlılığı ve Tanrı’nın yardımına güveni içerir. Tanrısal merhamete duyulan umutla beslenir." },
      "en": { "q": "What is interior penance?",
              "a": "It is the movement of a “contrite heart” (<em>Psalm</em> 51:19) drawn by divine grace to respond to the merciful love of God. This entails sorrow for and abhorrence of sins committed, a firm purpose not to sin again in the future and trust in the help of God. It is nourished by hope in divine mercy." } },
    { "type": "qa", "n": 301, "id": "soru-301", "ccc": "1434–1439",
      "tr": { "q": "Tövbe Hristiyan yaşamında hangi biçimleri alır?",
              "a": "Tövbe pek çok ve çeşitli yollarla ifade edilebilir; ama her şeyden önce oruç, dua ve sadaka ile. Tövbenin bu ve diğer birçok biçimi, bir Hristiyanın gündelik yaşamında, özellikle Büyük Perhiz döneminde ve tövbe günü olan Cuma günü uygulanabilir." },
      "en": { "q": "What forms does penance take in the Christian life?",
              "a": "Penance can be expressed in many and various ways but above all in fasting, prayer, and almsgiving. These and many other forms of penance can be practiced in the daily life of a Christian, particularly during the time of Lent and on the penitential day of Friday." } },
    { "type": "qa", "n": 302, "id": "soru-302", "ccc": "1440–1449",
      "tr": { "q": "Barışma sırrının temel öğeleri nelerdir?",
              "a": "Temel öğeler iki tanedir: Kutsal Ruh’un etkinliğiyle tövbeye gelen tövbekârın eylemleri ve Mesih’in adıyla bağışlamayı veren ve kefaretin yollarını belirleyen rahibin günahları çözmesi (absolüsyon)." },
      "en": { "q": "What are the essential elements of the sacrament of Reconciliation?",
              "a": "The essential elements are two: the acts of the penitent who comes to repentance through the action of the Holy Spirit, and the absolution of the priest who in the name of Christ grants forgiveness and determines the ways of making satisfaction." } },
    { "type": "qa", "n": 303, "id": "soru-303", "ccc": "1450–1460, 1487–1492",
      "tr": { "q": "Tövbekârın eylemleri nelerdir?",
              "a": "Bunlar şunlardır: özenli bir <em>vicdan muhasebesi</em>; Tanrı sevgisinden kaynaklandığında yetkin, başka nedenlere dayandığında eksik olan ve bir daha günah işlememe kararlılığını içeren <em>pişmanlık</em> (tövbe); günahların rahibe anlatılmasından oluşan <em>itiraf</em>; ve <em>kefaret</em>, yani günahın yol açtığı zararı onarmak için günah dinleyen rahibin tövbekâra verdiği belirli tövbe eylemlerinin yerine getirilmesi." },
      "en": { "q": "What are the acts of the penitent?",
              "a": "They are: a careful <em>examination of conscience</em>; <em>contrition</em> (or repentance), which is perfect when it is motivated by love of God and imperfect if it rests on other motives and which includes the determination not to sin again; <em>confession</em>, which consists in the telling of one’s sins to the priest; and <em>satisfaction</em> or the carrying out of certain acts of penance which the confessor imposes upon the penitent to repair the damage caused by sin." } },
    { "type": "qa", "n": 304, "id": "soru-304", "ccc": "1456",
      "tr": { "q": "Hangi günahlar itiraf edilmelidir?",
              "a": "Özenli bir vicdan muhasebesinin akla getirdiği, henüz itiraf edilmemiş bütün ağır günahlar Tövbe sırrına getirilmelidir. Ağır günahların itirafı, bağışlanma elde etmenin tek olağan yoludur." },
      "en": { "q": "Which sins must be confessed?",
              "a": "All grave sins not yet confessed, which a careful examination of conscience brings to mind, must be brought to the sacrament of Penance. The confession of serious sins is the only ordinary way to obtain forgiveness." } },
    { "type": "qa", "n": 305, "id": "soru-305", "ccc": "1457",
      "tr": { "q": "Kişi ölümcül günahlarını ne zaman itiraf etmekle yükümlüdür?",
              "a": "Ayırt etme yaşına ulaşmış her inanlı, ölümcül günahlarını en az yılda bir kez ve her zaman Kutsal Komünyon almadan önce itiraf etmekle yükümlüdür." },
      "en": { "q": "When is a person obliged to confess mortal sins?",
              "a": "Each of the faithful who has reached the age of discretion is bound to confess his or her mortal sins at least once a year and always before receiving Holy Communion." } },
    { "type": "qa", "n": 306, "id": "soru-306", "ccc": "1458",
      "tr": { "q": "Hafif günahlar neden kutsal sır niteliğindeki itirafın konusu olabilir?",
              "a": "Hafif günahların itirafı, kesinlikle gerekli olmasa bile, Kilise tarafından içtenlikle tavsiye edilir; çünkü doğru bir vicdan oluşturmamıza ve kötü eğilimlere karşı savaşmamıza yardım eder. Mesih tarafından iyileştirilmemizi ve Ruh’un yaşamında ilerlememizi sağlar." },
      "en": { "q": "Why can venial sins also be the object of sacramental confession?",
              "a": "The confession of venial sins is strongly recommended by the Church, even if this is not strictly necessary, because it helps us to form a correct conscience and to fight against evil tendencies. It allows us to be healed by Christ and to progress in the life of the Spirit." } },
    { "type": "qa", "n": 307, "id": "soru-307", "ccc": "1461–1466, 1495",
      "tr": { "q": "Bu kutsal sırrın görevlisi kimdir?",
              "a": "Mesih Barışma görevini havarilerine, onların ardılları olan piskoposlara ve piskoposların yardımcıları olan rahiplere emanet etmiştir; bunların hepsi böylece Tanrı’nın merhametinin ve adaletinin araçları olurlar. Günahları bağışlama yetkilerini <em>Baba, Oğul ve Kutsal Ruh’un adıyla</em> kullanırlar." },
      "en": { "q": "Who is the minister of this sacrament?",
              "a": "Christ has entrusted the ministry of Reconciliation to his apostles, to the bishops who are their successors and to the priests who are the collaborators of the bishops, all of whom become thereby instruments of the mercy and justice of God. They exercise their power of forgiving sins <em>in the name of the Father and of the Son and of the Holy Spirit</em>." } },
    { "type": "qa", "n": 308, "id": "soru-308", "ccc": "1463",
      "tr": { "q": "Bazı günahların bağışlanması kime ayrılmıştır?",
              "a": "Özellikle ağır bazı günahların (aforozla cezalandırılanlar gibi) bağışlanması Havarisel Makam’a, yerel piskoposa ya da onların yetkilendirdiği rahiplere ayrılmıştır. Ancak her rahip, ölüm tehlikesindeki bir kişiyi her türlü günahtan ve aforozdan bağışlayabilir." },
      "en": { "q": "To whom is the absolution of some sins reserved?",
              "a": "The absolution of certain particularly grave sins (like those punished by excommunication) is reserved to the Apostolic See or to the local bishop or to priests who are authorized by them. Any priest, however, can absolve a person who is in danger of death from any sin and excommunication." } },
    { "type": "qa", "n": 309, "id": "soru-309", "ccc": "1467",
      "tr": { "q": "Günah dinleyen rahip gizlilikle yükümlü müdür?",
              "a": "Bu görevin inceliği ve büyüklüğü ve insanlara gösterilmesi gereken saygı nedeniyle, günah dinleyen her rahip, hiçbir istisna olmaksızın ve çok ağır cezalar altında, “kutsal sır mührünü”, yani itirafta kendisine açıklanan günahlar hakkında mutlak gizliliği korumakla yükümlüdür." },
      "en": { "q": "Is a confessor bound to secrecy?",
              "a": "Given the delicacy and greatness of this ministry and the respect due to people every confessor, without any exception and under very severe penalties, is bound to maintain “the sacramental seal” which means absolute secrecy about the sins revealed to him in confession." } },
    { "type": "qa", "n": 310, "id": "soru-310", "ccc": "1468–1470, 1496",
      "tr": { "q": "Bu kutsal sırrın etkileri nelerdir?",
              "a": "Tövbe sırrının etkileri şunlardır: Tanrı’yla barışma ve dolayısıyla günahların bağışlanması; Kilise’yle barışma; yitirilmişse lütuf durumunun yeniden kazanılması; ölümcül günahların gerektirdiği sonsuz cezanın bağışlanması ve günahın sonucu olan geçici cezanın en azından bir kısmının bağışlanması; esenlik, vicdan huzuru ve ruhsal teselli; ve Hristiyan yaşamının mücadelesi için ruhsal gücün artması." },
      "en": { "q": "What are the effects of this sacrament?",
              "a": "The effects of the sacrament of Penance are: reconciliation with God and therefore the forgiveness of sins; reconciliation with the Church; recovery, if it has been lost, of the state of grace; remission of the eternal punishment merited by mortal sins, and remission, at least in part, of the temporal punishment which is the consequence of sin; peace, serenity of conscience and spiritual consolation; and an increase of spiritual strength for the struggle of Christian living." } },
    { "type": "qa", "n": 311, "id": "soru-311", "ccc": "1480–1484",
      "tr": { "q": "Bu kutsal sır bazı durumlarda genel itiraf ve genel bağışlamayla kutlanabilir mi?",
              "a": "Ağır zorunluluk durumlarında (yakın bir ölüm tehlikesinde olduğu gibi), Kilise’nin kurallarına uyulması ve ağır günahları zamanı gelince bireysel olarak itiraf etme niyetinin bulunması koşuluyla, genel itiraf ve genel bağışlamayla toplu bir Barışma kutlamasına başvurulabilir." },
      "en": { "q": "Can this sacrament be celebrated in some cases with a general confession and general absolution?",
              "a": "In cases of serious necessity (as in imminent danger of death) recourse may be had to a communal celebration of Reconciliation with general confession and general absolution, as long as the norms of the Church are observed and there is the intention of individually confessing one’s grave sins in due time." } },
    { "type": "qa", "n": 312, "id": "soru-312", "ccc": "1471–1479, 1498",
      "tr": { "q": "Endüljanslar nedir?",
              "a": "Endüljanslar, suçu zaten bağışlanmış günahların gerektirdiği geçici cezanın Tanrı önünde bağışlanmasıdır. Gerektiği gibi hazırlanmış olan Hristiyan inanlı, belirlenmiş koşullar altında endüljansı ya kendisi ya da ölmüşler için kazanır. Endüljanslar, kurtuluş lütfunun dağıtıcısı olarak Mesih’in ve Azizlerin erdemlerinin hazinesini paylaştıran Kilise’nin hizmeti aracılığıyla verilir." },
      "en": { "q": "What are indulgences?",
              "a": "Indulgences are the remission before God of the temporal punishment due to sins whose guilt has already been forgiven. The faithful Christian who is duly disposed gains the indulgence under prescribed conditions for either himself or the departed. Indulgences are granted through the ministry of the Church which, as the dispenser of the grace of redemption, distributes the treasury of the merits of Christ and the Saints." } },
    { "type": "heading", "level": 4, "id": "hastalarin-meshedilmesi-sirri",
      "tr": "Hastaların Meshedilmesi Sırrı",
      "en": "The Sacrament of Anointing of the Sick" },
    { "type": "qa", "n": 313, "id": "soru-313", "ccc": "1499–1502",
      "tr": { "q": "Eski Antlaşma’da hastalığa nasıl bakılıyordu?",
              "a": "Eski Antlaşma’da hastalık bir zayıflık işareti olarak yaşanıyor ve aynı zamanda gizemli bir biçimde günahla bağlantılı olarak algılanıyordu. Peygamberler hastalığın kişinin kendi günahları ve başkalarının günahları için kurtarıcı bir değeri de olabileceğini sezdiler. Böylece hastalık, insanların iyileşme dilediği Tanrı’nın huzurunda yaşanıyordu." },
      "en": { "q": "How was sickness viewed in the Old Testament?",
              "a": "In the Old Testament sickness was experienced as a sign of weakness and at the same time perceived as mysteriously bound up with sin. The prophets intuited that sickness could also have a redemptive value for one’s own sins and those of others. Thus sickness was lived out in the presence of God from whom people implored healing." } },
    { "type": "qa", "n": 314, "id": "soru-314", "ccc": "1503–1505",
      "tr": { "q": "İsa’nın hastalara duyduğu merhametin anlamı nedir?",
              "a": "İsa’nın hastalara duyduğu merhamet ve güçsüzleri pek çok kez iyileştirmesi, O’nunla birlikte Tanrı’nın Egemenliği’nin ve dolayısıyla günah, acı ve ölüm üzerindeki zaferin geldiğinin açık bir işaretiydi. Kendi çilesi ve ölümüyle acılarımıza yeni bir anlam verdi; acılarımız O’nunkiyle birleştiğinde bizim ve başkalarının arınması ve kurtuluşu için bir araç olabilir." },
      "en": { "q": "What is the significance of Jesus’ compassion for the sick?",
              "a": "The compassion of Jesus toward the sick and his many healings of the infirm were a clear sign that with him had come the Kingdom of God and therefore victory over sin, over suffering, and over death. By his own passion and death he gave new meaning to our suffering which, when united with his own, can become a means of purification and of salvation for us and for others." } },
    { "type": "qa", "n": 315, "id": "soru-315", "ccc": "1506–1513, 1526–1527",
      "tr": { "q": "Kilise’nin hastalara karşı tutumu nedir?",
              "a": "Rab’den hastaları iyileştirme görevini almış olan Kilise, hastalarla ilgilenerek ve onlara aracılık dualarıyla eşlik ederek bu görevi yerine getirmeye çalışır. Her şeyden önce Kilise, özellikle hastaların yararına yönelik bir kutsal sırra sahiptir. Bu kutsal sır Mesih tarafından kurulmuştur ve [[Aziz Yakup|Saint James]] tarafından tanıklık edilmiştir: “Aranızda hasta olan var mı? Kilise’nin ihtiyarlarını çağırsın; onlar da Rab’bin adıyla onu yağla meshedip onun için dua etsinler” (Yakup 5:14-15)." },
      "en": { "q": "What is the attitude of the Church toward the sick?",
              "a": "Having received from the Lord the charge to heal the sick, the Church strives to carry it out by taking care of the sick and accompanying them with her prayer of intercession. Above all, the Church possesses a sacrament specifically intended for the benefit of the sick. This sacrament was instituted by Christ and is attested by Saint James: “Is anyone among you sick? Let him call in the presbyters of the Church and let them pray over him and anoint him with oil in the name of the Lord” (<em>James</em> 5:14-15)." } },
    { "type": "qa", "n": 316, "id": "soru-316", "ccc": "1514–1515, 1528–1529",
      "tr": { "q": "Hastaların meshedilmesi sırrını kimler alabilir?",
              "a": "Her inanlı, hastalık ya da yaşlılık nedeniyle ölüm tehlikesine girmeye başladığı anda bu kutsal sırrı alabilir. Bu kutsal sırrı alan inanlılar, hastalıkları ağırlaşırsa ya da başka bir ağır hastalığa yakalanırlarsa onu birkaç kez alabilirler. Bu kutsal sırrın kutlanmasından önce, mümkünse, hasta kişinin bireysel itirafı yapılmalıdır." },
      "en": { "q": "Who can receive the sacrament of the anointing of the sick?",
              "a": "Any member of the faithful can receive this sacrament as soon as he or she begins to be in danger of death because of sickness or old age. The faithful who receive this sacrament can receive it several times if their illness becomes worse or another serious sickness afflicts them. The celebration of this sacrament should, if possible, be preceded by individual confession on the part of the sick person." } },
    { "type": "qa", "n": 317, "id": "soru-317", "ccc": "1516, 1530",
      "tr": { "q": "Bu kutsal sırrı kim verir?",
              "a": "Bu kutsal sır yalnızca rahipler (piskoposlar ya da presbiterler) tarafından verilebilir." },
      "en": { "q": "Who administers this sacrament?",
              "a": "This sacrament can be administered only by priests (bishops or presbyters)." } },
    { "type": "qa", "n": 318, "id": "soru-318", "ccc": "1517–1519, 1531",
      "tr": { "q": "Bu kutsal sır nasıl kutlanır?",
              "a": "Bu kutsal sırrın kutlanması esas olarak, piskopos tarafından kutsanmış olabilen yağla bir <em>meshetmeden</em> oluşur. Meshetme, hasta kişinin alnına ve ellerine (Roma ayininde) ya da bedenin başka yerlerine de (diğer ayinlerde) yapılır; buna, bu kutsal sırrın özel lütfunu dileyen rahibin <em>duası</em> eşlik eder." },
      "en": { "q": "How is this sacrament celebrated?",
              "a": "The celebration of this sacrament consists essentially in an <em>anointing</em> with oil which may be blessed by the bishop. The anointing is on the forehead and on the hands of the sick person (in the Roman rite) or also on other parts of the body (in the other rites) accompanied by the <em>prayer</em> of the priest who asks for the special grace of this sacrament." } },
    { "type": "qa", "n": 319, "id": "soru-319", "ccc": "1520–1523, 1532",
      "tr": { "q": "Bu kutsal sırrın etkileri nelerdir?",
              "a": "Bu kutsal sır, hasta kişiyi kendi iyiliği ve bütün Kilise’nin iyiliği için Mesih’in Çilesi’ne daha içten bir biçimde birleştiren özel bir lütuf verir. Teselli, esenlik, cesaret ve hasta kişi itirafta bulunamıyorsa günahların bağışlanmasını da sağlar. Bazen, Tanrı’nın isteği ise, bu kutsal sır bedensel sağlığın yeniden kazanılmasını bile sağlar. Her durumda bu Meshetme hasta kişiyi Baba’nın Evi’ne yolculuğa hazırlar." },
      "en": { "q": "What are the effects of this sacrament?",
              "a": "This sacrament confers a special grace which unites the sick person more intimately to the Passion of Christ for his good and for the good of all the Church. It gives comfort, peace, courage, and even the forgiveness of sins if the sick person is not able to make a confession. Sometimes, if it is the will of God, this sacrament even brings about the restoration of physical health. In any case this Anointing prepares the sick person for the journey to the Father’s House." } },
    { "type": "qa", "n": 320, "id": "soru-320", "ccc": "1524–1525",
      "tr": { "q": "Viaticum (Yol Azığı) nedir?",
              "a": "Viaticum, bu dünya yaşamından ayrılmak üzere olan ve sonsuz yaşama yolculuğa hazırlanan kişilerin aldığı Kutsal Efkaristiya’dır. Bu dünyadan Baba’ya geçiş anında alınan, ölüp ölüler arasından dirilen Mesih’in bedenine ve kanına katılım, sonsuz yaşamın tohumu ve dirilişin gücüdür." },
      "en": { "q": "What is Viaticum?",
              "a": "Viaticum is the Holy Eucharist received by those who are about to leave this earthly life and are preparing for the journey to eternal life. Communion in the body and blood of Christ who died and rose from the dead, received at the moment of passing from this world to the Father, is the seed of eternal life and the power of the resurrection." } },
    { "type": "heading", "level": 3, "id": "ucuncu-baslik-birligin-ve-gorevin-hizmetindeki-sirlar",
      "tr": "Üçüncü Başlık: Birliğin ve Görevin Hizmetindeki Sırlar",
      "en": "Chapter Three: The Sacraments at the Service of Communion and Mission" },
    { "type": "qa", "n": 321, "id": "soru-321", "ccc": "1533–1535",
      "tr": { "q": "Birliğin ve görevin hizmetindeki kutsal sırlar hangileridir?",
              "a": "Kutsal Rahiplik ve Evlilik olmak üzere iki kutsal sır, Tanrı Halkı’na hizmet etmek ve onu bina etmek üzere Kilise’deki özel bir görev için özel bir lütuf verir. Bu kutsal sırlar kilise birliğine ve başkalarının kurtuluşuna özel bir biçimde katkıda bulunur." },
      "en": { "q": "What are the sacraments at the service of communion and mission?",
              "a": "Two sacraments, Holy Orders and Matrimony, confer a special grace for a particular mission in the Church to serve and build up the People of God. These sacraments contribute in a special way to ecclesial communion and to the salvation of others." } },
    { "type": "heading", "level": 4, "id": "kutsal-rahiplik-sirri",
      "tr": "Kutsal Rahiplik Sırrı",
      "en": "The Sacrament of Holy Orders" },
    { "type": "qa", "n": 322, "id": "soru-322", "ccc": "1536",
      "tr": { "q": "Kutsal Rahiplik sırrı nedir?",
              "a": "Mesih’in havarilerine emanet ettiği görevin zamanın sonuna dek Kilise’de yerine getirilmeye devam ettiği kutsal sırdır." },
      "en": { "q": "What is the sacrament of Holy Orders?",
              "a": "It is the sacrament through which the mission entrusted by Christ to his apostles continues to be exercised in the Church until the end of time." } },
    { "type": "qa", "n": 323, "id": "soru-323", "ccc": "1537–1538",
      "tr": { "q": "Bu kutsal sırra neden Kutsal Rahiplik (Kutsal Derece) denir?",
              "a": "<em>Derece</em> (Latince <em>ordo</em>), özel bir kutsama (takdis) yoluyla girilen bir kilise topluluğunu belirtir. Kutsal Ruh’un özel bir armağanı aracılığıyla bu kutsal sır, kutsananları Tanrı Halkı’nın hizmeti için Mesih’in adıyla ve yetkisiyle <em>kutsal bir yetki</em> kullanabilir kılar." },
      "en": { "q": "Why is this sacrament called Holy Orders?",
              "a": "<em>Orders</em> designates an ecclesial body into which one enters by means of a special consecration (ordination). Through a special gift of the Holy Spirit, this sacrament enables the ordained to exercise a <em>sacred power</em> in the name and with the authority of Christ for the service of the People of God." } },
    { "type": "qa", "n": 324, "id": "soru-324", "ccc": "1539–1546, 1590–1591",
      "tr": { "q": "Kutsal Rahiplik sırrı Tanrı’nın kurtuluş tasarısında nasıl bir yer tutar?",
              "a": "Bu kutsal sır Eski Antlaşma’da Levililerin hizmetinde, [[Harun’un|Aaron]] kâhinliğinde ve yetmiş “İhtiyar”ın atanmasında (Çölde Sayım 11:25) önceden simgelenmişti. Bu öncül simgeler, haç kurbanıyla “Tanrı ile insanlar arasında tek aracı” (1 Timoteos 2:5), “[[Malkisedek|Melchizedek]] düzeni uyarınca Başkâhin” (İbraniler 5:10) olan Mesih İsa’da tamamlanır. Mesih’in tek rahipliği, hizmet rahipliğinde mevcut kılınır." },
      "en": { "q": "What place does the sacrament of Holy Orders have in the divine plan of salvation?",
              "a": "This sacrament was prefigured in the Old Covenant in the service of the Levites, in the priesthood of Aaron, and in the institution of the seventy “Elders” (<em>Numbers</em> 11:25). These prefigurations find their fulfillment in Christ Jesus who by the sacrifice of the cross is the “one mediator between God and man” (<em>1 Timothy</em> 2:5), the “High Priest according to the order of Melchizedek” (<em>Hebrews</em> 5:10). The one priesthood of Christ is made present in the ministerial priesthood." } },
    { "type": "quote",
      "tr": "“Gerçek rahip yalnızca Mesih’tir; diğerleri yalnızca O’nun görevlileridir.” ([[Aquinolu Aziz Tomas|Saint Thomas Aquinas]])",
      "en": "“Only Christ is the true priest, the others being only his ministers.” (Saint Thomas Aquinas)" },
    { "type": "qa", "n": 325, "id": "soru-325", "ccc": "1554, 1593",
      "tr": { "q": "Kutsal Rahiplik sırrını oluşturan dereceler nelerdir?",
              "a": "Kutsal Rahiplik sırrı, Kilise’nin organik yapısı için vazgeçilmez olan üç dereceden oluşur: piskoposluk, rahiplik (presbiterlik) ve diyakonluk." },
      "en": { "q": "What are the degrees that make up the sacrament of Holy Orders?",
              "a": "The sacrament of Holy Orders is composed of three degrees which are irreplaceable for the organic structure of the Church: the episcopate, the presbyterate and the diaconate." } },
    { "type": "qa", "n": 326, "id": "soru-326", "ccc": "1557–1558",
      "tr": { "q": "Piskoposluk takdisinin etkisi nedir?",
              "a": "Piskoposluk takdisi Kutsal Rahiplik sırrının doluluğunu verir. Piskoposu havarilerin meşru bir ardılı yapar ve onu Papa ve diğer piskoposlarla birlikte bütün kiliselerin sorumluluğunu paylaşmak üzere piskoposlar kuruluna katar. Ona öğretme, kutsallaştırma ve yönetme görevlerini verir." },
      "en": { "q": "What is the effect of episcopal ordination?",
              "a": "Episcopal ordination confers the fullness of the sacrament of Holy Orders. It makes the bishop a legitimate successor of the apostles and integrates him into the episcopal college to share with the Pope and the other bishops care for all the churches. It confers on him the offices of teaching, sanctifying, and ruling." } },
    { "type": "qa", "n": 327, "id": "soru-327", "ccc": "1560–1561",
      "tr": { "q": "Yerel bir Kilise’de Piskoposa emanet edilen görev nedir?",
              "a": "Kendisine yerel bir Kilise’nin sorumluluğu emanet edilen piskopos, o Kilise’nin görünür başı ve birliğinin temelidir. O Kilise uğruna, Mesih’in vekili olarak çobanlık görevini yerine getirir ve kendi rahipleri ve diyakozları ona yardım eder." },
      "en": { "q": "What is the office confided to a Bishop in a particular Church?",
              "a": "The bishop to whom the care of a particular Church is entrusted is the visible head and foundation of unity for that Church. For the sake of that Church, as vicar of Christ, he fulfills the office of shepherd and is assisted by his own priests and deacons." } },
    { "type": "qa", "n": 328, "id": "soru-328", "ccc": "1562–1567, 1595",
      "tr": { "q": "Rahipliğe takdisin etkisi nedir?",
              "a": "Ruh’un meshi rahibi, onu rahip Mesih’e benzeten ve Baş olan Mesih’in adıyla hareket etmesini sağlayan silinmez, ruhsal bir mühürle mühürler. Piskoposlar derecesinin bir yardımcısı olarak, Müjde’yi vaaz etmek, tanrısal tapınmayı, özellikle de görevinin gücünü aldığı Efkaristiya’yı kutlamak ve inanlıların çobanı olmak üzere kutsanır." },
      "en": { "q": "What is the effect of ordination to the priesthood?",
              "a": "The anointing of the Spirit seals the priest with an indelible, spiritual character that configures him to Christ the priest and enables him to act in the name of Christ the Head. As a co-worker of the order of bishops he is consecrated to preach the Gospel, to celebrate divine worship, especially the Eucharist from which his ministry draws its strength, and to be a shepherd of the faithful." } },
    { "type": "qa", "n": 329, "id": "soru-329", "ccc": "1568",
      "tr": { "q": "Rahip kendine özgü görevini nasıl yerine getirir?",
              "a": "Rahip, evrensel bir görev için takdis edilmiş olsa da görevini yerel bir Kilise’de yerine getirir. Bu görev, “presbiterlik heyetini” oluşturan diğer rahiplerle kutsal sır kardeşliği içinde sürdürülür. Piskoposla birlik içinde ve ona bağlı olarak yerel Kilise’nin sorumluluğunu taşırlar." },
      "en": { "q": "How does a priest carry out his proper ministry?",
              "a": "A priest, although ordained for a universal mission, exercises his ministry in a particular Church. This ministry is pursued in sacramental brotherhood with other priests who form the “presbyterate”. In communion with the bishop, and depending upon him, they bear responsibility for the particular Church." } },
    { "type": "qa", "n": 330, "id": "soru-330", "ccc": "1569–1571, 1596",
      "tr": { "q": "Diyakonluğa takdisin etkisi nedir?",
              "a": "Herkesin hizmetkârı olan Mesih’e benzeyen diyakoz, Kilise’ye hizmet için takdis edilir. Bu hizmeti, kendi piskoposunun yetkisi altında, Söz, tanrısal tapınma, pastoral ilgi ve sevgi görevleriyle yerine getirir." },
      "en": { "q": "What is the effect of the ordination to the diaconate?",
              "a": "The deacon, configured to Christ the servant of all, is ordained for service to the Church. He carries out this service under the authority of his proper bishop by the ministry of the Word, of divine worship, of pastoral care and of charity." } },
    { "type": "qa", "n": 331, "id": "soru-331", "ccc": "1572–1574, 1597",
      "tr": { "q": "Kutsal Rahiplik sırrı nasıl kutlanır?",
              "a": "Kutsal Rahiplik sırrı, üç derecesinin her birinde, Piskoposun takdis edilecek kişinin başına <em>ellerini koyması</em> ve görkemli takdis <em>duasını</em> okumasıyla verilir. Bu duayla Piskopos, takdis edilecek kişi adına Tanrı’dan Kutsal Ruh’un özel dökülmesini ve takdis edildiği göreve özgü Ruh’un armağanlarını diler." },
      "en": { "q": "How is the sacrament of Holy Orders celebrated?",
              "a": "The sacrament of Holy Orders is conferred, in each of its three degrees, by means of the <em>imposition of hands</em> on the head of the ordinand by the Bishop who pronounces the solemn <em>prayer</em> of consecration. With this prayer he asks God on behalf of the ordinand for the special outpouring of the Holy Spirit and for the gifts of the Spirit proper to the ministry to which he is being ordained." } },
    { "type": "qa", "n": 332, "id": "soru-332", "ccc": "1575–1576, 1600",
      "tr": { "q": "Bu kutsal sırrı kim verebilir?",
              "a": "Kutsal Rahiplik sırrını yalnızca havarilerin ardılları olarak geçerli biçimde takdis edilmiş piskoposlar verebilir." },
      "en": { "q": "Who can confer this sacrament?",
              "a": "Only validly ordained bishops, as successors of the apostles, can confer the sacrament of Holy Orders." } },
    { "type": "qa", "n": 333, "id": "soru-333", "ccc": "1577–1578, 1598",
      "tr": { "q": "Bu kutsal sırrı kim alabilir?",
              "a": "Bu kutsal sır yalnızca vaftiz edilmiş bir erkek tarafından geçerli olarak alınabilir. Kilise, Rab’bin Kendisinin yaptığı bu seçimle bağlı olduğunu kabul eder. Hiç kimse Kutsal Rahiplik sırrını almayı talep edemez; Kilise yetkilileri tarafından göreve uygun görülmesi gerekir." },
      "en": { "q": "Who can receive this sacrament?",
              "a": "This sacrament can only be validly received by a baptized man. The Church recognizes herself as bound by this choice made by the Lord Himself. No one can demand to receive the sacrament of Holy Orders, but must be judged suitable for the ministry by the authorities of the Church." } },
    { "type": "qa", "n": 334, "id": "soru-334", "ccc": "1579–1580, 1599",
      "tr": { "q": "Kutsal Rahiplik sırrını almak için bekâr olmak gerekli midir?",
              "a": "Piskoposluk için bekâr olmak her zaman gereklidir. Latin Kilisesi’nde rahiplik için, inancını uygulayan, bekâr ve “Göklerin Egemenliği uğruna” (Matta 19:12) bekâr bir yaşam sürmeye devam etmeyi amaçlayan erkekler seçilir. Doğu Kiliselerinde takdis edildikten sonra evlenmeye izin verilmez. Evli erkekler sürekli diyakonluğa takdis edilebilir." },
      "en": { "q": "Is it necessary to be celibate to receive the sacrament of Holy Orders?",
              "a": "It is always necessary to be celibate for the episcopacy. For the priesthood in the Latin Church men who are practicing Catholics and celibate are chosen, men who intend to continue to live a celibate life “for the kingdom of heaven” (<em>Matthew</em> 19:12). In the Eastern Churches marriage is not permitted after one has been ordained. Married men can be ordained to the permanent diaconate." } },
    { "type": "qa", "n": 335, "id": "soru-335", "ccc": "1581–1589",
      "tr": { "q": "Kutsal Rahiplik sırrının etkileri nelerdir?",
              "a": "Bu kutsal sır, alan kişiyi kutsal sırrın ilgili derecelerine göre Rahip, Peygamber ve Kral olarak üçlü görevi içinde Mesih’e benzeten özel bir Kutsal Ruh dökülmesi sağlar. Takdis silinmez bir ruhsal mühür verir; bu nedenle tekrarlanamaz ya da sınırlı bir süre için verilemez." },
      "en": { "q": "What are the effects of the sacrament of Holy Orders?",
              "a": "This sacrament yields a special outpouring of the Holy Spirit which configures the recipient to Christ in his triple office as Priest, Prophet, and King, according to the respective degrees of the sacrament. Ordination confers an indelible spiritual character and therefore cannot be repeated or conferred for a limited time." } },
    { "type": "qa", "n": 336, "id": "soru-336", "ccc": "1547–1553, 1592",
      "tr": { "q": "Rahiplik görevi hangi yetkiyle yerine getirilir?",
              "a": "Takdis edilmiş rahipler kutsal görevlerini yerine getirirken kendi yetkileriyle, hatta topluluğun görevlendirmesi ya da vekâletiyle değil, Baş olan Mesih’in Kişisi’nde ve Kilise’nin adına konuşur ve hareket ederler. Bu nedenle hizmet rahipliği, Mesih’in hizmeti için kurduğu bütün inanlılara ortak olan rahiplikten yalnızca derece bakımından değil, özünde farklıdır." },
      "en": { "q": "With what authority is the priestly ministry exercised?",
              "a": "Ordained priests in the exercise of their sacred ministry speak and act not on their own authority, nor even by mandate or delegation of the community, but rather in the Person of Christ the Head and in the name of the Church. Therefore, the ministerial priesthood differs essentially and not just in degree from the priesthood common to all the faithful for whose service Christ instituted it." } },
    { "type": "heading", "level": 4, "id": "evlilik-sirri",
      "tr": "Evlilik Sırrı",
      "en": "The Sacrament of Matrimony" },
    { "type": "qa", "n": 337, "id": "soru-337", "ccc": "1601–1605",
      "tr": { "q": "Tanrı’nın erkek ve kadınla ilgili tasarısı nedir?",
              "a": "Sevgi olan ve erkeği ve kadını sevgi için yaratan Tanrı, onları sevmeye çağırdı. Erkeği ve kadını yaratarak onları evlilikte içten bir yaşam ve sevgi birliğine çağırdı: “Böylece onlar artık iki değil, tek bedendir” (Matta 19:6). Tanrı onları kutsayarak şöyle dedi: “Verimli olun, çoğalın” (Yaratılış 1:28)." },
      "en": { "q": "What is the plan of God regarding man and woman?",
              "a": "God who is love and who created man and woman for love has called them to love. By creating man and woman he called them to an intimate communion of life and of love in marriage: “So that they are no longer two, but one flesh” (<em>Matthew</em> 19:6). God said to them in blessing “Be fruitful and multiply” (<em>Genesis</em> 1:28)." } },
    { "type": "qa", "n": 338, "id": "soru-338", "ccc": "1659–1660",
      "tr": { "q": "Tanrı Evliliği hangi amaçlar için kurmuştur?",
              "a": "Yaratıcı tarafından kurulan ve kendine özgü yasalarla donatılan erkek ile kadının evlilik birliği, doğası gereği çiftin birliğine ve iyiliğine, çocukların doğurulmasına ve eğitimine yöneliktir. Kökendeki tanrısal tasarıya göre bu evlilik birliği, İsa Mesih’in doğruladığı gibi çözülmezdir: “Tanrı’nın birleştirdiğini insan ayırmasın” (Markos 10:9)." },
      "en": { "q": "For what ends has God instituted Matrimony?",
              "a": "The marital union of man and woman, which is founded and endowed with its own proper laws by the Creator, is by its very nature ordered to the communion and good of the couple and to the generation and education of children. According to the original divine plan this conjugal union is indissoluble, as Jesus Christ affirmed: “What God has joined together, let no man put asunder” (<em>Mark</em> 10:9)." } },
    { "type": "qa", "n": 339, "id": "soru-339", "ccc": "1606–1608",
      "tr": { "q": "Günah evliliği nasıl tehdit eder?",
              "a": "Tanrı’nın erkek ve kadın arasında kurduğu birlikte bir kırılmaya yol açan ilk günah yüzünden evlilik birliği çoğu zaman anlaşmazlık ve sadakatsizlikle tehdit edilir. Ancak Tanrı sonsuz merhametiyle erkeğe ve kadına, yaşamlarının birliğini kökendeki tanrısal tasarıyla uyumlu kılma lütfunu verir." },
      "en": { "q": "How does sin threaten marriage?",
              "a": "Because of original sin, which caused a rupture in the God-given communion between man and woman, the union of marriage is very often threatened by discord and infidelity. However, God in his infinite mercy gives to man and woman the grace to bring the union of their lives into accord with the original divine plan." } },
    { "type": "qa", "n": 340, "id": "soru-340", "ccc": "1609–1611",
      "tr": { "q": "Eski Antlaşma evlilik hakkında ne öğretir?",
              "a": "Tanrı halkına, her şeyden önce Yasa’nın ve Peygamberlerin öğretisi aracılığıyla, evliliğin birliğini ve çözülmezliğini adım adım daha derinden kavramasında yardım etti. Tanrı’nın İsrail’le yaptığı evlilik antlaşması, Tanrı’nın Oğlu İsa Mesih’in gelini olan Kilise’yle kurduğu yeni antlaşmayı hazırladı ve önceden simgeledi." },
      "en": { "q": "What does the Old Testament teach about marriage?",
              "a": "God helped his people above all through the teaching of the Law and the Prophets to deepen progressively their understanding of the unity and indissolubility of marriage. The nuptial covenant of God with Israel prepared for and prefigured the new covenant established by Jesus Christ the Son of God, with his spouse, the Church." } },
    { "type": "qa", "n": 341, "id": "soru-341", "ccc": "1612–1617, 1661",
      "tr": { "q": "Mesih Evliliğe hangi yeni öğeyi kattı?",
              "a": "Mesih yalnızca evliliğin kökendeki düzenini yeniden kurmakla kalmadı, onu bir kutsal sır onuruna yükseltti; eşlere, evliliklerini Mesih’in gelini olan Kilise’ye duyduğu sevginin bir simgesi olarak yaşamaları için özel bir lütuf verdi: “Ey kocalar, Mesih Kilise’yi nasıl sevdiyse, siz de karılarınızı öyle sevin” (Efesliler 5:25)." },
      "en": { "q": "What new element did Christ give to Matrimony?",
              "a": "Christ not only restored the original order of matrimony but raised it to the dignity of a sacrament, giving spouses a special grace to live out their marriage as a symbol of Christ’s love for his bride the Church: “Husbands, love your wives as Christ loves the Church” (<em>Ephesians</em> 5:25)." } },
    { "type": "qa", "n": 342, "id": "soru-342", "ccc": "1618–1620",
      "tr": { "q": "Herkes evlenmekle yükümlü müdür?",
              "a": "Evlilik herkes için bir yükümlülük değildir; özellikle de Tanrı bazı erkek ve kadınları Göklerin Egemenliği uğruna bekâret ya da bekârlık yaşamı içinde Rab İsa’yı izlemeye çağırdığı için. Bunlar Rab’bin işlerine yoğunlaşmak ve O’nu hoşnut etmeye çalışmak için Evliliğin büyük iyiliğinden vazgeçerler. Mesih’in sevgisinin mutlak üstünlüğünün ve O’nun yüce dönüşünün ateşli bekleyişinin bir işareti olurlar." },
      "en": { "q": "Are all obliged to get married?",
              "a": "Matrimony is not an obligation for everyone, especially since God calls some men and women to follow the Lord Jesus in a life of virginity or of celibacy for the sake of the Kingdom of Heaven. These renounce the great good of Matrimony to concentrate on the things of the Lord and seek to please him. They become a sign of the absolute supremacy of Christ’s love and of the ardent expectation of his glorious return." } },
    { "type": "qa", "n": 343, "id": "soru-343", "ccc": "1621–1624",
      "tr": { "q": "Evlilik sırrı nasıl kutlanır?",
              "a": "Evlilik eşleri Kilise’de kamusal bir yaşam durumuna yerleştirdiği için, litürjik kutlaması kamusaldır; bir rahibin (ya da Kilise tarafından yetkilendirilmiş bir tanığın) ve diğer tanıkların huzurunda gerçekleşir." },
      "en": { "q": "How is the sacrament of Matrimony celebrated?",
              "a": "Since Matrimony establishes spouses in a public state of life in the Church, its liturgical celebration is public, taking place in the presence of a priest (or of a witness authorized by the Church) and other witnesses." } },
    { "type": "qa", "n": 344, "id": "soru-344", "ccc": "1625–1632, 1662–1663",
      "tr": { "q": "Evlilik rızası nedir?",
              "a": "Evlilik rızası, bir erkek ile bir kadın sadık ve verimli bir sevgi antlaşmasını yaşamak üzere kendilerini birbirlerine geri dönülmez biçimde verme isteklerini açıkladıklarında verilir. Evliliği oluşturan rıza olduğundan, rıza vazgeçilmez ve yeri doldurulamazdır. Geçerli bir evlilik için rızanın konusu gerçek Evlilik olmalı ve rıza, zorlama ya da baskıyla belirlenmemiş, bilinçli ve özgür bir insani eylem olmalıdır." },
      "en": { "q": "What is matrimonial consent?",
              "a": "Matrimonial consent is given when a man and a woman manifest the will to give themselves to each other irrevocably in order to live a covenant of faithful and fruitful love. Since consent constitutes Matrimony, it is indispensable and irreplaceable. For a valid marriage the consent must have as its object true Matrimony, and be a human act which is conscious and free and not determined by duress or coercion." } },
    { "type": "qa", "n": 345, "id": "soru-345", "ccc": "1633–1637",
      "tr": { "q": "Eşlerden biri Katolik değilse ne gereklidir?",
              "a": "<em>Karma</em> bir evlilik (bir Katolik ile Katolik olmayan vaftiz edilmiş biri arasında), meşruiyet için kilise yetkilisinin iznini gerektirir. <em>Din farklılığı</em> durumunda (bir Katolik ile vaftiz edilmemiş biri arasında) geçerlilik için bir muafiyet (dispensasyon) gereklidir. Her iki durumda da eşlerin evliliğin temel amaçlarını ve özelliklerini kabul etmeyi dışlamamaları esastır. Ayrıca Katolik tarafın, Katolik olmayan tarafa da bildirilmiş olan, imanında sebat etme ve çocuklarının vaftizini ve Katolik eğitimini güvence altına alma yükümlülüğünü kabul etmesi gereklidir." },
      "en": { "q": "What is required when one of the spouses is not a Catholic?",
              "a": "A <em>mixed</em> marriage (between a Catholic and a baptized non-Catholic) needs for liceity the permission of ecclesiastical authority. In a case of <em> disparity of cult</em> (between a Catholic and a non-baptized person) a dispensation is required for validity. In both cases, it is essential that the spouses do not exclude the acceptance of the essential ends and properties of marriage. It is also necessary for the Catholic party to accept the obligation, of which the non-Catholic party has been advised, to persevere in the faith and to assure the baptism and Catholic education of their children." } },
    { "type": "qa", "n": 346, "id": "soru-346", "ccc": "1638–1642",
      "tr": { "q": "Evlilik sırrının etkileri nelerdir?",
              "a": "Evlilik sırrı eşler arasında sürekli ve tek eşli bir <em>bağ</em> kurar. Eşlerin rızasını Tanrı’nın Kendisi mühürler. Bu nedenle vaftiz edilmiş kişiler arasında onaylanmış ve tamamlanmış bir evlilik asla çözülemez. Ayrıca bu kutsal sır, eşlere evlilik yaşamlarında kutsallığa erişmek, çocuk armağanını sorumlulukla kabul etmek ve onların eğitimini sağlamak için gerekli lütfu bağışlar." },
      "en": { "q": "What are the effects of the sacrament of Matrimony?",
              "a": "The sacrament of Matrimony establishes a perpetual and exclusive <em>bond</em> between the spouses. God himself seals the consent of the spouses. Therefore, a marriage which is ratified and consummated between baptized persons can never be dissolved. Furthermore, this sacrament bestows upon the spouses the grace necessary to attain holiness in their married life and to accept responsibly the gift of children and provide for their education." } },
    { "type": "qa", "n": 347, "id": "soru-347", "ccc": "1645–1648",
      "tr": { "q": "Evlilik sırrına hangi günahlar ağır biçimde karşıttır?",
              "a": "Zina ve çok eşlilik evlilik sırrına karşıttır; çünkü erkek ve kadının eşit onuruyla ve evlilik sevgisinin birliği ve tekliğiyle çelişirler. Diğer günahlar arasında, evlilik sevgisini çocuk armağanından yoksun bırakan, doğurganlık potansiyelinin bilerek reddedilmesi ve evliliğin çözülmezliğine aykırı olan boşanma vardır." },
      "en": { "q": "What sins are gravely opposed to the sacrament of Matrimony?",
              "a": "Adultery and polygamy are opposed to the sacrament of matrimony because they contradict the equal dignity of man and woman and the unity and exclusivity of married love. Other sins include the deliberate refusal of one’s procreative potential which deprives conjugal love of the gift of children and divorce which goes against the indissolubility of marriage." } },
    { "type": "qa", "n": 348, "id": "soru-348", "ccc": "1629, 1649",
      "tr": { "q": "Kilise eşlerin fiziksel olarak ayrı yaşamasına ne zaman izin verir?",
              "a": "Kilise, ciddi nedenlerle birlikte yaşamaları fiilen olanaksız hale geldiğinde, barışmaları için umut olsa bile, eşlerin fiziksel olarak ayrı yaşamalarına izin verir. Ancak eşi yaşadığı sürece kişi, evlilik geçersiz olmadıkça ve kilise yetkilisi tarafından geçersiz ilan edilmedikçe, yeni bir birlik kurmakta özgür değildir." },
      "en": { "q": "When does the Church allow the physical separation of spouses?",
              "a": "The Church permits the physical separation of spouses when for serious reasons their living together becomes practically impossible, even though there may be hope for their reconciliation. As long as one’s spouse lives, however, one is not free to contract a new union, except if the marriage be null and be declared so by ecclesiastical authority." } },
    { "type": "qa", "n": 349, "id": "soru-349", "ccc": "1650–1651, 1665",
      "tr": { "q": "Kilise’nin boşanıp yeniden evlenen kişilere karşı tutumu nedir?",
              "a": "Kilise, Rabbine sadık olduğu için, medeni olarak boşanıp yeniden evlenen kişilerin birliğini tanıyamaz. “Karısını boşayıp başka bir kadınla evlenen, karısına karşı zina etmiş olur. Kocasını boşayıp başka bir adamla evlenen kadın da zina etmiş olur” (Markos 10:11-12). Kilise bu kişilere özenli bir ilgi gösterir ve onları iman, dua, sevgi işleri ve çocuklarının Hristiyan eğitimi içinde bir yaşama teşvik eder. Ancak nesnel olarak Tanrı’nın yasasına aykırı olan durumları sürdüğü sürece, kutsal sır bağışlamasını alamaz, Kutsal Komünyon alamaz ya da bazı kilise sorumluluklarını üstlenemezler." },
      "en": { "q": "What is the attitude of the Church toward those people who are divorced and then remarried?",
              "a": "The Church, since she is faithful to her Lord, cannot recognize the union of people who are civilly divorced and remarried. “Whoever divorces his wife and marries another, commits adultery against her; and if she divorces her husband and marries another, she commits adultery” (<em>Mark</em> 10:11-12). The Church manifests an attentive solicitude toward such people and encourages them to a life of faith, prayer, works of charity and the Christian education of their children. However, they cannot receive sacramental absolution, take Holy Communion, or exercise certain ecclesial responsibilities as long as their situation, which objectively contravenes God’s law, persists." } },
    { "type": "qa", "n": 350, "id": "soru-350", "ccc": "1655–1658, 1666",
      "tr": { "q": "Hristiyan aileye neden <em>ev kilisesi</em> denir?",
              "a": "Hristiyan aileye ev kilisesi denir, çünkü aile, Tanrı’nın ailesi olarak Kilise’nin topluluk ve aile niteliğini gösterir ve yaşar. Ailenin her üyesi, kendi rolüne uygun olarak vaftiz rahipliğini uygular ve aileyi bir lütuf ve dua topluluğu, insani ve Hristiyan erdemlerin okulu ve imanın çocuklara ilk duyurulduğu yer haline getirmeye katkıda bulunur." },
      "en": { "q": "Why is the Christian family called a <em>domestic church</em>?",
              "a": "The Christian family is called the domestic church because the family manifests and lives out the communal and familial nature of the Church as the family of God. Each family member, in accord with their own role, exercises the baptismal priesthood and contributes toward making the family a community of grace and of prayer, a school of human and Christian virtue and the place where the faith is first proclaimed to children." } },
    { "type": "heading", "level": 3, "id": "dorduncu-baslik-diger-liturjik-kutlamalar",
      "tr": "Dördüncü Başlık: Diğer Litürjik Kutlamalar",
      "en": "Chapter Four: Other Liturgical Celebrations" },
    { "type": "heading", "level": 4, "id": "sakramentaller",
      "tr": "Sakramentaller",
      "en": "The Sacramentals" },
    { "type": "qa", "n": 351, "id": "soru-351", "ccc": "1667–1672, 1677–1678",
      "tr": { "q": "Sakramentaller nedir?",
              "a": "Sakramentaller, yaşamın farklı durumlarını kutsal kılmak için Kilise tarafından kurulmuş kutsal işaretlerdir. Haç işareti ve başka işaretlerle birlikte yapılan bir duayı içerirler. Önemli bir yer tutan sakramentaller arasında şunlar vardır: Tanrı’ya övgü ve O’nun armağanlarını elde etmek için dua olan kutsamalar, kişilerin kutsanması ve nesnelerin Tanrı’ya tapınma için adanması." },
      "en": { "q": "What are the sacramentals?",
              "a": "These are sacred signs instituted by the Church to sanctify different circumstances of life. They include a prayer accompanied by the sign of the cross and other signs. Among the sacramentals which occupy an important place are: blessings, which are the praise of God and a prayer to obtain his gifts, the consecration of persons and the dedication of things for the worship of God." } },
    { "type": "qa", "n": 352, "id": "soru-352", "ccc": "1673",
      "tr": { "q": "Eksorsizm (şeytan çıkarma) nedir?",
              "a": "Kilise, yetkisiyle ve İsa’nın adıyla bir kişinin ya da nesnenin Kötü Olan’ın gücüne karşı korunmasını ve onun egemenliğinden çıkarılmasını dilediğinde buna eksorsizm denir. Bu, olağan biçimde Vaftiz ayininde yapılır. <em>Büyük eksorsizm</em> denen görkemli bir eksorsizm ancak piskopos tarafından yetkilendirilmiş bir rahip tarafından yapılabilir." },
      "en": { "q": "What is an exorcism?",
              "a": "When the Church asks with its authority in the name of Jesus that a person or object be protected against the power of the Evil One and withdrawn from his dominion, it is called an exorcism. This is done in ordinary form in the rite of Baptism. A solemn exorcism, called a <em>major exorcism,</em> can be performed only by a priest authorized by the bishop." } },
    { "type": "qa", "n": 353, "id": "soru-353", "ccc": "1674–1676, 1679",
      "tr": { "q": "Hangi halk dindarlığı biçimleri Kilise’nin kutsal sır yaşamına eşlik eder?",
              "a": "Hristiyan halkının dinsel duyarlılığı, Kilise’nin kutsal sır yaşamına eşlik eden çeşitli dindarlık biçimlerinde her zaman ifade bulmuştur: kutsal emanetlere (röliklere) saygı, tapınak ziyaretleri, hac yolculukları, tören alayları, Haç Yolu ve Tespih gibi. Kilise, halk dindarlığının sahih biçimlerini imanın ışığıyla aydınlatır ve destekler." },
      "en": { "q": "What forms of popular piety accompany the sacramental life of the Church?",
              "a": "The religious sense of the Christian people has always found expression in the various forms of piety which accompany the sacramental life of the Church such as the veneration of relics, visits to sanctuaries, pilgrimages, processions, the stations of the cross and the rosary. The Church sheds the light of faith upon and fosters authentic forms of popular piety." } },
    { "type": "heading", "level": 4, "id": "hristiyan-cenaze-torenleri",
      "tr": "Hristiyan Cenaze Törenleri",
      "en": "Christian Funerals" },
    { "type": "qa", "n": 354, "id": "soru-354", "ccc": "1680–1683",
      "tr": { "q": "Kutsal sırlar ile bir Hristiyanın ölümü arasındaki ilişki nedir?",
              "a": "Mesih’te ölen Hristiyan, yeryüzündeki varoluşunun sonunda, Vaftiz’de başlayan, Konfirmasyon’da güçlenen ve göksel şölenin önden tadı olan Efkaristiya’da beslenen o yeni yaşamın tamamlanmasına ulaşır. Bir Hristiyanın ölümünün anlamı, tek umudumuz olan Mesih’in ölümü ve Dirilişinin ışığında açıklık kazanır. Mesih İsa’da ölen Hristiyan “bedenden ayrılıp Rab’bin yanında yaşamaya” (2 Korintliler 5:8) gider." },
      "en": { "q": "What is the relationship between the sacraments and the death of a Christian?",
              "a": "The Christian who dies in Christ reaches at the end of his earthly existence the fulfillment of that new life which was begun in Baptism, strengthened in Confirmation, and nourished in the Eucharist, the foretaste of the heavenly banquet. The meaning of the death of a Christian becomes clear in the light of the death and Resurrection of Christ our only hope. The Christian who dies in Christ Jesus goes “away from the body to be at home with the Lord” (<em>2 Corinthians</em> 5:8)." } },
    { "type": "qa", "n": 355, "id": "soru-355", "ccc": "1684–1685",
      "tr": { "q": "Cenaze ayinleri neyi ifade eder?",
              "a": "Çeşitli bölgelerin durumlarına ve geleneklerine uygun olarak farklı ayinlerle kutlansa da cenaze törenleri, diriliş umudu içinde Hristiyan ölümünün Paskalya niteliğini ifade eder. Ayrıca, özellikle ölmüşlerin canlarının arınması için edilen dua aracılığıyla onlarla birliğin anlamını gösterir." },
      "en": { "q": "What do funeral rites express?",
              "a": "Although celebrated in different rites in keeping with the situations and traditions of various regions, funerals express the paschal character of Christian death in hope of the resurrection. They also manifest the meaning of communion with the departed particularly through prayer for the purification of their souls." } },
    { "type": "qa", "n": 356, "id": "soru-356", "ccc": "1686–1690",
      "tr": { "q": "Cenaze törenlerinin başlıca anları nelerdir?",
              "a": "Cenaze ayinleri genellikle dört ana bölümden oluşur: ölmüş kişinin bedeninin topluluk tarafından teselli ve umut sözleriyle karşılanması, Söz litürjisi, Efkaristiya Kurbanı ve ölmüş kişinin canının sonsuz yaşamın Kaynağı olan Tanrı’ya emanet edildiği, bedenin ise diriliş umuduyla gömüldüğü veda." },
      "en": { "q": "What are the main moments in funerals?",
              "a": "Usually, funeral rites consist of four principal parts: welcoming the body of the deceased by the community with words of comfort and hope, the liturgy of the Word, the Eucharistic Sacrifice, and the farewell in which the soul of the departed is entrusted to God, the Source of eternal life, while the body is buried in the hope of the resurrection." } }
  ]
}/*JSON-END*/;
